const t=[{id:1,code:"OPS-MIS-101",icon:"ShieldCheck",accent:"#dc2626",title:"رسالة عمل الدفاع المدني ومبادئه وأساسه القانوني",subtitle:"لماذا يوجد الدفاع المدني وعلى أي مبادئ يعمل",summary:"الدفاع المدني جهاز إنساني يحمي الناس من أخطار الحرائق والكوارث الطبيعية والطوارئ. في هذا الدرس تتعرف إلى مهامه الدولية ومبادئ عمله وما تحدده القوانين وتعليمات السلطة المختصة.",blocks:[{heading:"ما الدفاع المدني؟",body:"الدفاع المدني هو جميع الأعمال والاستعدادات التي تهدف إلى حماية السكان المدنيين من الأخطار، ومساعدتهم على تجاوز آثار الكارثة، وتوفير الظروف اللازمة لبقائهم. وهذا العمل ليس إطفاء الحرائق فقط؛ بل يشمل الإنذار والإنقاذ والإسعافات الأولية والإخلاء والإيواء. يبقى منتسبو الدفاع المدني جاهزين ليلًا ونهارًا لأن الطوارئ لا تُنذر بموعدها. والمواطنون جزء مهم من هذا العمل: كل من يتصل بالرقم 115 اتصالًا صحيحًا، أو يترك الطريق مفتوحًا، أو ينبّه جارًا مسنًّا، يشارك في حماية الأرواح. هذا الدرس هو بداية قسم «عمل الدفاع المدني»، وتُبنى عليه الدروس التالية."},{heading:"المهام الدولية (البروتوكول الأول، المادة 61)",body:`يعرّف البروتوكول الإضافي الأول لاتفاقيات جنيف (1977) في المادة 61 الدفاع المدني بأنه أداء مهام إنسانية لحماية السكان المدنيين. وهذه قائمة المهام:

• الإنذار.
• الإجلاء.
• تهيئة المخابئ وإدارتها.
• تطبيق تدابير التعتيم.
• الإنقاذ.
• الخدمات الطبية بما فيها الإسعافات الأولية.
• مكافحة الحرائق.
• تقصّي المناطق الخطرة ووسمها.
• مكافحة التلوث وتدابير الوقاية المماثلة.
• توفير المأوى والمؤن في حالات الطوارئ.
• المساعدة الطارئة في إعادة النظام إلى المناطق المنكوبة.
• الإصلاح العاجل للمرافق العامة التي لا غنى عنها.
• الدفن العاجل للموتى.
• المساعدة في حفظ الأعيان اللازمة للبقاء.
• الأنشطة المكمّلة بما فيها التخطيط والتنظيم.`},{heading:"مبادئ العمل",body:`يقوم عمل الدفاع المدني على عدة مبادئ:

• حياة الإنسان أولًا: الأرواح ثم الممتلكات ثم البيئة.
• سلامة الفريق: المنقذ المصاب لا يستطيع إنقاذ غيره.
• الحياد والمساواة: تُقدَّم المساعدة للجميع بحسب الحاجة ومن دون تمييز.
• التنظيم والقيادة: لكل حادث قائد واحد وخطة واضحة.
• التنسيق: مع الإسعاف (122) والشرطة (104) والجهات الأخرى.
• الوقاية قبل الاستجابة: التفتيش والتوعية والتدريب تحمي أرواحًا أكثر من الإطفاء وحده.
• الأمانة وحماية المعلومات الشخصية للمتضررين.`},{heading:"الحماية والشارة الدولية",body:"ينص البروتوكول الأول على احترام وحماية أجهزة الدفاع المدني المدنية وأفرادها ومبانيها وموادها، لكي تتمكن من أداء مهامها الإنسانية. والشارة الدولية المميزة للدفاع المدني مثلث أزرق متساوي الأضلاع على خلفية برتقالية (المادة 66). والغرض منها أن يُعرف أفراد الدفاع المدني ومركباته بسهولة. ولا يجوز استعمالها لأغراض أخرى، لأن ذلك يضر بثقة الناس بها. وبالنسبة إلى المواطن العادي فمعنى ذلك أن منتسب الدفاع المدني يخدم الجميع، وأن عرقلة عمله أو انتحال صفته قد يعرّض الأرواح للخطر."},{heading:"القوانين والتعليمات المحلية",body:"في كل دولة يحدد قانون أو أكثر مهام الدفاع المدني وصلاحياته وواجبات المواطنين والمؤسسات، مثل شروط السلامة في المباني أو واجب المساعدة أثناء الكوارث. لا يذكر هذا الدرس أسماء القوانين المحلية وأرقامها، لأنها لم تُؤكَّد رسميًّا بعد من المديرية. وكلما احتجت إلى معلومة قانونية فاتبع تعليمات الدفاع المدني والسلطة المختصة، واطلب النص الرسمي المنشور، لا ما يُتداول في مواقع التواصل. والقاعدة هي: ما يقوم به الدفاع المدني يقوم به استنادًا إلى القانون وبأمر السلطة المختصة."}],steps:[{title:"تعرّف إلى الخطر",detail:"حدّد أي مهمة من مهام الدفاع المدني تتصل بهذا الحادث: حريق أو إنقاذ أو إخلاء أو إغاثة."},{title:"احمِ الأرواح",detail:"سلامتك وسلامة الناس أولًا؛ الممتلكات تأتي بعد ذلك. لا تعرّض نفسك للخطر.",critical:!0},{title:"أبلغ",detail:"اتصل بالرقم 115 (و122 إن وُجد مصابون): المكان وما حدث وعدد الأشخاص والأخطار.",critical:!0},{title:"اتبع التعليمات",detail:"عند وصول الفريق نفّذ تعليمات قائد الحادث والسلطة المختصة."}],warnings:["لا تستعمل شارة الدفاع المدني أو زيّه لأغراض شخصية: فذلك يضعف ثقة الناس بالشارة.","لا تقطع طريق مركبات الدفاع المدني ولا تتجمع حول المنتسبين: كل دقيقة تأخير قد تكلّف حياة."],tips:["احفظ الرقم 115 للحريق والإنقاذ، و122 للإسعاف، و104 للشرطة.","خذ المعلومات القانونية من النص الرسمي وتعليمات الدفاع المدني فقط.","إذا أردت أن تتطوع فاسأل مديرية الدفاع المدني عن دورات التدريب المتاحة."],activity:{prompt:"يقول لك صديق: «الدفاع المدني يطفئ الحرائق فقط». بماذا تجيبه؟",options:[{text:"صحيح، مهمته الإطفاء فقط.",correct:!1,feedback:"غير صحيح: تعدّد المادة 61 خمس عشرة مهمة، منها الإنذار والإنقاذ والإيواء."},{text:"يشمل الإطفاء والإنقاذ والإنذار والإخلاء والإسعافات الأولية والإيواء أيضًا.",correct:!0,feedback:"صحيح: هذا ما تنص عليه القائمة الدولية للمهام."},{text:"مهمته حماية المباني الحكومية فقط.",correct:!1,feedback:"غير صحيح: مهمته حماية جميع السكان المدنيين."},{text:"يعمل في زمن الحرب فقط.",correct:!1,feedback:"غير صحيح: يستجيب الدفاع المدني يوميًّا للحرائق والحوادث والكوارث الطبيعية."}]},caseStudy:[{prompt:"في قرية ارتفع منسوب النهر وغمرت المياه البيوت. وصل فريق من الدفاع المدني. بحسب مهام المادة 61، أي مهمة تأتي أولًا؟",options:[{text:"إنذار الناس وإنقاذ من هم في خطر.",correct:!0,feedback:"صحيح: الأرواح أولًا؛ فالإنذار والإنقاذ في المقدمة."},{text:"إصلاح طرق القرية.",correct:!1,feedback:"هذه مهمة لاحقة بعد أن لا يبقى أحد في خطر."},{text:"حصر الأضرار في الممتلكات.",correct:!1,feedback:"الممتلكات تأتي بعد الأرواح."}]},{prompt:"خرج الناس من بيوتهم لكن لا مكان لهم يبيتون فيه. ما المهمة التالية؟",options:[{text:"توفير المأوى والمؤن الطارئة بالتنسيق مع جهات الإغاثة.",correct:!0,feedback:"صحيح: هذه إحدى مهام المادة 61 وينسقها قسم الإغاثة والإيواء."},{text:"أمر الناس بالعودة إلى بيوتهم.",correct:!1,feedback:"العودة فقط بعد أن تعلن السلطة المختصة سلامة المكان."},{text:"يعود الفريق وينتهي العمل.",correct:!1,feedback:"لا ينتهي العمل بالإنقاذ؛ فالإيواء والمؤن من المهام أيضًا."}]}],quiz:[{question:"ما الشارة الدولية المميزة للدفاع المدني؟",options:[{text:"مثلث أزرق على خلفية برتقالية.",correct:!0},{text:"صليب أحمر على خلفية بيضاء.",correct:!1},{text:"دائرة صفراء على خلفية زرقاء.",correct:!1},{text:"مثلث أحمر على خلفية بيضاء.",correct:!1}],explanation:"تحدد المادة 66 من البروتوكول الأول مثلثًا أزرق متساوي الأضلاع على البرتقالي؛ أما الصليب الأحمر فشارة الخدمات الطبية."},{question:"وصل فريق إلى حريق. أي ترتيب للأولويات صحيح بحسب مبادئ العمل؟",options:[{text:"الممتلكات ثم البيئة ثم الأرواح.",correct:!1},{text:"الأرواح ثم الممتلكات ثم البيئة.",correct:!0},{text:"البيئة ثم الأرواح ثم الممتلكات.",correct:!1},{text:"كل ما هو أقرب إلى الباب.",correct:!1}],explanation:"المبدأ الأول أن حياة الإنسان أولًا ثم الممتلكات والبيئة."},{question:"يريد منقذ دخول مبنى مليء بالدخان دون معدات حماية. أي مبدأ يمنع ذلك؟",options:[{text:"الحياد والمساواة.",correct:!1},{text:"سلامة الفريق.",correct:!0},{text:"حماية المعلومات الشخصية.",correct:!1},{text:"الوقاية قبل الاستجابة.",correct:!1}],explanation:"المنقذ المصاب يصبح ضحية أخرى ولا يستطيع إنقاذ أحد."},{question:"تريد أن تعرف ما يقوله القانون عن شروط السلامة في متجر. ما أفضل طريقة؟",options:[{text:"اقرأ منشورًا على مواقع التواصل شاركه كثير من الناس.",correct:!1},{text:"اطلب النص الرسمي والتعليمات من مديرية الدفاع المدني.",correct:!0},{text:"افعل كما يفعل المتجر المجاور لأنه يعمل أيضًا.",correct:!1},{text:"اتصل بالرقم 122 واسأل موظف الإسعاف عن القانون.",correct:!1}],explanation:"المعلومة القانونية الصحيحة تأتي من النص الرسمي والسلطة المختصة؛ والرقم 122 للإسعاف في الطوارئ الطبية."},{question:"أي من هذه المهام ليست في قائمة المادة 61؟",options:[{text:"إدارة المخابئ.",correct:!1},{text:"تقصّي المناطق الخطرة.",correct:!1},{text:"جباية الضرائب من المتاجر.",correct:!0},{text:"مكافحة الحرائق.",correct:!1}],explanation:"مهام المادة 61 كلها إنسانية لحماية السكان؛ وجباية الضرائب ليست منها."},{question:"شخص يرتدي زيًّا يشبه زي الدفاع المدني ويطلب مالًا من الناس «للتفتيش». ماذا تفعل؟",options:[{text:"أدفع المال تجنبًا للمشاكل وأطلب منه إيصالًا.",correct:!1},{text:"لا أدفع وأبلغ مديرية الدفاع المدني أو الشرطة (104).",correct:!0},{text:"أتشاجر معه وأنزع زيه بالقوة أمام الناس.",correct:!1},{text:"أنشر صورته على مواقع التواصل ولا أفعل شيئًا آخر.",correct:!1}],explanation:"انتحال صفة منتسب الدفاع المدني يضر بثقة الناس؛ والتصرف الصحيح إبلاغ الجهات الرسمية لا الاشتباك. واسأل المديرية عن إجراءات التفتيش الرسمية."}]},{id:2,code:"OPS-ORG-102",icon:"Network",accent:"#2563eb",title:"كيف تُنظَّم مديرية الدفاع المدني",subtitle:"الأقسام ومهامها وكيف تعمل معًا",summary:"تتكون مديرية الدفاع المدني من عدة أقسام: بعضها يعمل في الميدان وبعضها يسانده. يعرّف هذا الدرس بالأقسام وأسمائها ويبيّن كيف تعمل معًا في الحادث الواحد. وهو دليل تعريفي، وليس الهيكل الإداري الرسمي.",blocks:[{heading:"لماذا التنظيم مهم؟",body:"تأتي الكوارث والحوادث بأنواع مختلفة: حريق في منزل، أو حادث مرور على طريق، أو فيضان في قرية، أو مادة خطرة في مصنع. ولا يستطيع فريق واحد أن يؤدي كل هذه الأعمال بإتقان. لذلك تُقسَّم المديرية إلى أقسام مختصة، لكل قسم تدريبه ومعداته ومهامه. لكن التقسيم وحده لا يكفي: يجب أن تعمل الأقسام كلها بخطة واحدة وقيادة واحدة حتى لا يتكرر العمل ولا يُنسى شيء. والأقسام الواردة في هذا الدرس مأخوذة من دليل أقسام الدفاع المدني في هذا البرنامج وبالأسماء نفسها."},{heading:"أقسام القيادة والإسناد",points:["المديرية والإدارة: تنظّم الأولويات والموارد. تخطّط للاستعداد وتتابع عمل الفرق. تربط العمل الميداني بالجهات المعنية.","غرفة العمليات والطوارئ: تستقبل معلومات الحوادث وتنظمها. تنسّق توجيه الفرق المناسبة. تتابع التطورات وتشارك التحديثات مع فرق الاستجابة.","الوقاية والتفتيش والسلامة: تراجع ترتيبات الوقاية من الحرائق والسلامة. ترصد النواقص وتوثّق الملاحظات. تساند المتابعة والتوعية بالسلامة في المباني وأماكن العمل.","الإعلام والتوعية: تشرح رسائل السلامة للجمهور. تعدّ مواد توعوية وتساند التواصل المجتمعي. تنشر المعلومات بالتنسيق مع المصادر المخوَّلة.","التعليم والتدريب: تنظّم التعلّم والتمارين العملية. تطوّر الاستعداد والمهارات المهنية. تساند تعليم السلامة في المدارس وبيئات التعلّم الأخرى.","اللوجستيات والآليات: تساند جاهزية المركبات والمعدات. تنظّم احتياجات الإمداد والصيانة. تساعد الفرق الميدانية على توفير الموارد اللازمة للعمل."]},{heading:"الأقسام الميدانية",points:["الإطفاء: تستجيب الفرق المختصة للحرائق. تعمل على الحد من انتشار النار وحماية الأشخاص. تنسّق عملها مع فرق الإنقاذ والإسناد.","الإسعافات الأولية: يقدّم المستجيبون المدرَّبون الإسعافات الأولية ضمن حدود تأهيلهم. ينسّقون مع الخدمات الطبية. يساندون نقل الأشخاص المحتاجين إلى رعاية طبية.","الإنقاذ البري: تساعد الفرق المختصة في حوادث المرور والانهيارات والمناطق الصعبة. تقيّم احتياجات الوصول والإنقاذ. تنسّق الإخلاء الآمن مع بقية المستجيبين.","المواد الخطرة: تقيّم الفرق المختصة حوادث المواد الخطرة. تنظّم الدخول إلى المنطقة وتنسّق إجراءات الحماية. تتعاون مع الجهات المسؤولة عن المواد المعنية.","الإنقاذ المائي: تساعد فرق مؤهلة في الطوارئ المرتبطة بالمياه. تستخدم معدات الإنقاذ والقوارب المناسبة. تنسّق الإنقاذ والإخلاء أثناء الفيضانات.","الألغام والمقذوفات غير المنفلقة: يتولى هذا المجال اختصاصيون مخوَّلون. يقيّمون مخاطر الأجسام المشتبه بها ويؤمّنون المنطقة. ينسّقون مع الجهات المختصة؛ هذا الدليل لا يشرح التعامل أو الإزالة.","الإغاثة والإيواء: تساند المتضررين من الطوارئ. تنسّق الإيواء وتوزيع الاحتياجات الأساسية. تتعاون مع المنظمات الإنسانية والجهات الخدمية."]},{heading:"كيف تعمل الأقسام معًا في حادث واحد",body:"تخيّل حريقًا يندلع في مبنى سكني. تستقبل غرفة العمليات والطوارئ البلاغ وتوجّه فرق الإطفاء والإنقاذ. يُخمد الإطفائيون النار، ويُخرج المنقذون المحاصَرين، وتنسّق فرق الإسعافات الأولية مع الإسعاف. توفّر اللوجستيات الماء والوقود والمعدات. وإذا بقيت أسر بلا مأوى يدخل قسم الإغاثة والإيواء. وبعد الحادث يفحص قسم الوقاية والتفتيش والسلامة أسباب الحريق ونواقص السلامة، ويعدّ قسم الإعلام والتوعية رسالة توعوية للجمهور. ويدير هذه الأعمال كلها قائد حادث واحد."},{heading:"المواطن والأقسام",body:"يصل المواطن إلى غرفة العمليات عبر الرقم 115، وهي توجّه القسم المناسب. لا تحتاج إلى معرفة أي قسم يجب أن يأتي: يكفي أن تقول بوضوح ماذا حدث وأين. أما الأعمال اليومية مثل أسئلة التفتيش على السلامة أو دورات التدريب أو حملات التوعية فاتبع فيها تعليمات المديرية؛ وطريقة التواصل الرسمية مع كل قسم ما زالت بحاجة إلى تأكيد. وتذكّر أن هذا الدليل ليس الهيكل الإداري الرسمي، وأن أسماء الأقسام وعددها قد تختلف من مديرية إلى أخرى."}],steps:[{title:"استقبال البلاغ",detail:"تستقبل غرفة العمليات والطوارئ المعلومات وتنظمها.",critical:!0},{title:"توجيه الفرق المناسبة",detail:"بحسب نوع الحادث: الإطفاء أو الإنقاذ البري أو المواد الخطرة أو الإنقاذ المائي.",critical:!0},{title:"قائد واحد",detail:"يوزّع قائد الحادث المهام وينسّق مع الإسعاف والشرطة."},{title:"الإسناد",detail:"توفّر اللوجستيات المعدات، ويساند قسم الإغاثة والإيواء المتضررين."},{title:"بعد الحادث",detail:"يحدد التفتيش الأسباب، وينقل الإعلام والتوعية الدروس إلى الجمهور."}],warnings:["لا تتصل بأرقام المنتسبين الشخصية عند وقوع حادث؛ اتصل بالرقم 115 لتوجّه غرفة العمليات الفريق المناسب.","هذا الدليل ليس الهيكل الإداري الرسمي؛ ارجع إلى تعليمات المديرية لمعرفة المهام والصلاحيات الرسمية."],tips:["اذكر نوع الحادث بوضوح عند الاتصال ليُرسَل الفريق الصحيح.","لأسئلة التفتيش وشروط السلامة اسأل المديرية عن الطريق الرسمي.","إذا أردت التطوع فقسم التعليم والتدريب هو نقطة البداية."],activity:{prompt:"انقلب قارب صيد في النهر وفي الماء شخصان. أي قسم يُرسَل أولًا؟",options:[{text:"الإنقاذ المائي مع الإسعافات الأولية.",correct:!0,feedback:"صحيح: لديها فرق مؤهلة وقوارب مناسبة لذلك."},{text:"الوقاية والتفتيش والسلامة.",correct:!1,feedback:"هذا القسم يفتّش ولا ينقذ في الماء."},{text:"اللوجستيات والآليات.",correct:!1,feedback:"اللوجستيات تساند، أما الإنقاذ فعمل الفرق المؤهلة."},{text:"الإعلام والتوعية.",correct:!1,feedback:"التوعية مهمة لكن ليس في الدقائق الأولى للإنقاذ."}]},caseStudy:[{prompt:"في مصنع تنبعث رائحة نفاذة من خزان ويشكو عاملان من صداع. أي قسم توجّه غرفة العمليات؟",options:[{text:"المواد الخطرة مع الإسعافات الأولية والإسعاف.",correct:!0,feedback:"صحيح: يلزم تقييم المادة وحماية الأشخاص."},{text:"الإنقاذ المائي فقط.",correct:!1,feedback:"الحادث لا علاقة له بالمياه."},{text:"الإغاثة والإيواء.",correct:!1,feedback:"يأتي هذا القسم لاحقًا إن بقي الناس بلا مأوى."}]},{prompt:"وصلت الفرق. يريد صاحب المصنع التحدث مع كل فريق على حدة. ما الصحيح؟",options:[{text:"يقدّم معلوماته (المادة والمكان والعمال) لقائد الحادث.",correct:!0,feedback:"صحيح: قائد واحد يستقبل المعلومات ويوزعها على الفرق."},{text:"يدخل بنفسه المصنع ليغلق الخزان.",correct:!1,feedback:"هذا يعرّضه للخطر؛ لا يدخل إلا الفريق المختص بمعدات الحماية."},{text:"يعطي كل فريق أوامر مختلفة.",correct:!1,feedback:"الأوامر المتعددة تسبب الفوضى؛ الأوامر تصدر عن قائد الحادث."}]}],quiz:[{question:"أي قسم يستقبل اتصال 115 ويوجّه الفرق؟",options:[{text:"غرفة العمليات والطوارئ.",correct:!0},{text:"قسم التعليم والتدريب.",correct:!1},{text:"قسم اللوجستيات والآليات.",correct:!1},{text:"قسم الإغاثة والإيواء.",correct:!1}],explanation:"تستقبل غرفة العمليات معلومات الحوادث وتنسّق توجيه الفرق المناسبة."},{question:"يجد مواطن مقذوفًا غير منفلق في حديقته. أي قسم معني وماذا يفعل المواطن؟",options:[{text:"الألغام والمقذوفات غير المنفلقة؛ لا يلمسه ويبتعد ويتصل بالرقم 115.",correct:!0},{text:"الألغام والمقذوفات؛ ينقله إلى مكان بعيد ليسهل على الفريق أخذه.",correct:!1},{text:"الوقاية والتفتيش؛ يلتقط صورة عن قرب ويرسلها إلى أصدقائه.",correct:!1},{text:"اللوجستيات؛ يحفر بنفسه بأداة لإخراجه.",correct:!1}],explanation:"هذا المجال للاختصاصيين المخوَّلين فقط؛ المواطن لا يلمس ولا يقترب ويُبعد الناس ويبلّغ."},{question:"بعد حريق في سوق، أي قسم يفحص أسباب الحريق ونواقص السلامة؟",options:[{text:"الإنقاذ البري للحوادث.",correct:!1},{text:"الوقاية والتفتيش والسلامة.",correct:!0},{text:"الإغاثة والإيواء والدعم.",correct:!1},{text:"الإنقاذ المائي والقوارب.",correct:!1}],explanation:"يراجع هذا القسم ترتيبات السلامة ويرصد النواقص ويوثّق الملاحظات."},{question:"لماذا تعمل كل الأقسام في الحادث تحت قائد واحد؟",options:[{text:"كي لا يتكرر العمل ولا يُنسى شيء.",correct:!0},{text:"كي يعمل كل قسم كما يشاء.",correct:!1},{text:"كي يقل عدد الفرق في المكان.",correct:!1},{text:"كي لا يأتي الإسعاف والشرطة.",correct:!1}],explanation:"القائد الواحد والخطة الواحدة يمنعان الفوضى والتكرار ويسهّلان التنسيق مع 122 و104."},{question:"بعد فيضان بقيت عشر أسر بلا بيوت. أي قسم ينسّق الإيواء؟",options:[{text:"الإعلام والتوعية.",correct:!1},{text:"المواد الخطرة.",correct:!1},{text:"الإغاثة والإيواء.",correct:!0},{text:"الإطفاء.",correct:!1}],explanation:"ينسّق قسم الإغاثة والإيواء الإيواء وتوزيع الاحتياجات الأساسية مع المنظمات الإنسانية."},{question:"تريد تنظيم تمرين إخلاء في مدرستك. أي قسم أنسب للسؤال؟",options:[{text:"التعليم والتدريب.",correct:!0},{text:"غرفة العمليات عبر 115.",correct:!1},{text:"الألغام والمقذوفات غير المنفلقة.",correct:!1},{text:"الإنقاذ المائي.",correct:!1}],explanation:"ينظّم قسم التعليم والتدريب التمارين العملية وتعليم السلامة في المدارس؛ اترك 115 للطوارئ."}]},{id:3,code:"OPS-RSP-103",icon:"PhoneCall",accent:"#ea580c",title:"من الاتصال بالرقم 115 إلى موقع الحادث: دورة الاستجابة",subtitle:"الاتصال والتوجيه والوصول والتقييم والتسليم",summary:"يبدأ كل حادث باتصال وينتهي بتسليم الموقع. يشرح هذا الدرس مراحل دورة الاستجابة: ما المعلومات التي يقدمها المتصل، وكيف توجّه غرفة العمليات الفرق، وما تفعله الفرق في الموقع، وكيف يُسلَّم الموقع.",blocks:[{heading:"المرحلة الأولى: الاتصال",body:`المتصل هو الحلقة الأولى في سلسلة الإنقاذ. والمعلومات الصحيحة الموجزة تختصر وقت التوجيه. قل بهذا الترتيب:

• المكان: المنطقة والشارع ومعلم معروف والطابق.
• ماذا حدث: حريق أو حادث أو انهيار أو فيضان أو غاز.
• عدد المصابين أو المحاصَرين.
• الأخطار: غاز أو أسلاك أو مواد أو مبنى متصدع.
• اسمك ورقم هاتفك.

لا تُنهِ المكالمة حتى يطلب منك الموظف ذلك. وإذا لم تعرف العنوان فابحث عن معالم قريبة مثل جامع أو مدرسة أو متجر معروف. اتصل بالرقم 115 للحريق والإنقاذ، وبالرقم 122 إن وُجد مصابون، وبالاثنين إن اجتمع الأمران.`},{heading:"المرحلة الثانية: التوجيه",body:"تسجّل غرفة العمليات والطوارئ المعلومات وتوجّه الفرق المناسبة بحسب نوع الحادث وحجمه: الإطفاء أو الإنقاذ البري أو المواد الخطرة أو الإنقاذ المائي. وعند الحاجة يُبلَّغ الإسعاف (122) والشرطة (104). وقد يعطيك موظف الاتصال تعليمات حتى وصول الفرق، مثل الخروج من المبنى أو الابتعاد عن شيء خطر. وتشارك غرفة العمليات المعلومات الجديدة باستمرار مع الفرق في الطريق. أما إجراءات التوجيه ومعاييره في مديرية دهوك (أي فريق لأي حادث وزمن الوصول) فلم تُنشر رسميًّا بعد، ولذلك لا يذكر هذا الدرس أي رقم."},{heading:"المرحلة الثالثة: الوصول والتقييم",body:"عند وصول الفريق يكون العمل الأول تقييم الموقع (Size-up) قبل أي عمل آخر. ينظر قائد الحادث في هذه الأسئلة: هل هناك أرواح في خطر وكم عددها؟ ما الأخطار، مثل الغاز أو الكهرباء أو الانهيار أو المواد؟ إلى أين ينتشر الحريق أو الحادث؟ هل الفرق والمعدات المتاحة كافية أم يلزم الإسناد؟ وبحسب الإجابات يضع القائد الخطة ويوزّع المهام ويحدد طوقًا آمنًا حول الموقع. ويقدّم الموجودون في المكان، مثل صاحب المبنى أو المتصل، معلومات مهمة للقائد: من ما زال في الداخل، وأين أُغلق الغاز، وأين المداخل."},{heading:"المرحلة الرابعة: العمل والتسليم والختام",body:"تعمل الفرق بترتيب: الأرواح، ثم وقف الانتشار، ثم حماية الممتلكات. ويُسلَّم المصابون إلى الإسعاف بتسليم واضح: ماذا حدث، وماذا قُدِّم، ومتى. وبعد السيطرة على الحادث تفحص الفرق الموقع حتى لا تعود النار إلى الاشتعال ولا يبقى خطر خفي. ثم يُسلَّم الموقع رسميًّا إلى الجهة المسؤولة، مثل صاحب المبنى أو الشرطة أو البلدية، مع تعليمات متى وكيف يمكن العودة. وختام الدورة التوثيق وتنظيف المعدات وتجهيزها للحادث التالي، ودراسة الأسباب والدروس المستفادة."},{heading:"دور المواطن في كل مرحلة",body:`يستطيع المواطنون تسريع دورة الاستجابة أو إبطاءها:

• في أثناء الاتصال، كن هادئًا وتكلم بوضوح.
• اترك الطريق مفتوحًا لمركبات الطوارئ ولا تلحق بها.
• أرسل شخصًا إلى الطريق ليرشد الفريق إلى المكان إن كان ذلك آمنًا.
• ابقَ خارج الطوق الآمن ولا تلتقط الصور.
• قدّم معلوماتك للقائد واتبع التعليمات.
• لا تعد إلى الموقع حتى تسمح الجهة المسؤولة.`}],steps:[{title:"الاتصال",detail:"المكان، وما حدث، وعدد الأشخاص، والأخطار، والاسم والرقم؛ لا تُنهِ المكالمة حتى يُطلب منك.",critical:!0},{title:"التوجيه",detail:"توجّه غرفة العمليات الفرق المناسبة وتبلّغ 122 و104 عند الحاجة."},{title:"الوصول والتقييم",detail:"الأرواح والأخطار والانتشار والحاجة إلى إسناد؛ ثم الخطة والطوق الآمن.",critical:!0},{title:"العمل",detail:"الأرواح ثم وقف الانتشار ثم الممتلكات.",critical:!0},{title:"التسليم",detail:"يُسلَّم المصابون إلى الإسعاف بوضوح، ويُسلَّم الموقع بعد الفحص للجهة المسؤولة."},{title:"الختام",detail:"التوثيق وتجهيز المعدات والدروس المستفادة."}],warnings:["لا تُجرِ بلاغًا كاذبًا إلى 115: الفريق الذي يذهب لبلاغ كاذب قد لا يكون متاحًا لحادث حقيقي في مكان آخر.","بعد وصول الفريق لا تدخل الطوق الآمن ولا تعد إلى المبنى دون إذن.","لا تلحق بمركبات الطوارئ ولا تتوقف على الطريق للمشاهدة."],tips:["اعرف المعالم المعروفة قرب بيتك لتصف المكان بسرعة.","إن كان آمنًا فأرسل شخصًا إلى الطريق ليرشد الفريق.","جهّز المعلومات المهمة للقائد (من في الداخل، الغاز، المفاتيح)."],activity:{prompt:"ترى حادث سيارات وشخص محاصر في سيارة. بماذا تبدأ اتصالك بالرقم 115؟",options:[{text:"بالمكان: الطريق والاتجاه ومعلم قريب.",correct:!0,feedback:"صحيح: دون المكان لا يصل الفريق؛ ابدأ بالمكان."},{text:"بسرد كل ما رأيته من البداية.",correct:!1,feedback:"السرد الطويل يضيّع الوقت؛ المكان أولًا ثم ملخص الحادث."},{text:"باسمك وعملك.",correct:!1,feedback:"الاسم والرقم مهمان لكنهما بعد المكان والحادث."},{text:"بالسؤال عن موعد وصول الفريق.",correct:!1,feedback:"هذا السؤال لا يقدم معلومة؛ ينطلق الفريق بعد معرفة المكان."}]},caseStudy:[{prompt:"تتصل بالرقم 115 بسبب دخان من بيت الجيران. يقول الموظف «ابقَ على الخط». ماذا تفعل؟",options:[{text:"أبقى على الخط وأجيب عن الأسئلة من مكان آمن.",correct:!0,feedback:"صحيح: قد يكون لدى الموظف أسئلة مهمة أو تعليمات."},{text:"أغلق الخط لأذهب وأنظر.",correct:!1,feedback:"إغلاق الخط يقطع المعلومات والاقتراب من الدخان خطر."},{text:"أتحدث مع شخص آخر على هاتف آخر.",correct:!1,feedback:"هذا يشتت انتباهك عن أسئلة الموظف."}]},{prompt:"وصل فريق الإطفاء. صاحب البيت في الخارج ويعلم أن ابنته في الطابق الثاني. ماذا يفعل؟",options:[{text:"يبلّغ قائد الفريق فورًا: من، وفي أي طابق، وفي أي غرفة.",correct:!0,feedback:"صحيح: هذه أساس التقييم وتوجّه الإنقاذ."},{text:"يدخل بنفسه ليحضر ابنته.",correct:!1,feedback:"قد يصبح ضحية أخرى؛ الفريق يدخل بمعدات الحماية."},{text:"يبقى صامتًا كي لا يربك الفريق.",correct:!1,feedback:"الصمت يخفي معلومة حياتية."}]}],quiz:[{question:"في الاتصال بالرقم 115، أي معلومة تأتي أولًا؟",options:[{text:"اسم المتصل.",correct:!1},{text:"مكان الحادث.",correct:!0},{text:"وقت بدء الحادث.",correct:!1},{text:"لون المبنى.",correct:!1}],explanation:"إذا انقطع الاتصال فبمعرفة المكان يستطيع الفريق الوصول؛ لذا المكان أولًا."},{question:"وصل الفريق. ماذا يفعل القائد قبل أي عمل؟",options:[{text:"تقييم الموقع: الأرواح والأخطار والانتشار والحاجات.",correct:!0},{text:"يبدأ فورًا برش الماء على المبنى كله من كل الجهات.",correct:!1},{text:"يكتب تقريرًا للمديرية.",correct:!1},{text:"يتحدث إلى الصحفيين عن الحادث.",correct:!1}],explanation:"التقييم يحدد الخطة ويمنع العمل العشوائي الخطر."},{question:"ترى سيارة إطفاء بصفارتها على الطريق. ماذا تفعل؟",options:[{text:"ألحق بها لأعرف إلى أين تذهب.",correct:!1},{text:"أفسح الطريق بأمان ولا ألحق بها.",correct:!0},{text:"أقف وسط الطريق وأنتظر.",correct:!1},{text:"أسرع لأصل إلى التقاطع قبلها.",correct:!1}],explanation:"إفساح الطريق بأمان يختصر زمن الوصول؛ واللحاق بها يسد الطريق ويزيد الخطر."},{question:"أُخمد الحريق. متى تستطيع الأسرة العودة إلى البيت؟",options:[{text:"فور اختفاء اللهب.",correct:!1},{text:"بعد أن يخفّ الدخان.",correct:!1},{text:"بعد الفحص وإذن الجهة المسؤولة.",correct:!0},{text:"بعد أن تجمع الفرق معداتها وتغادر الشارع.",correct:!1}],explanation:"قد يعود الاشتعال ويكون المبنى ضعيفًا؛ فالعودة فقط بعد الفحص والإذن."},{question:"هناك حريق وشخص مصاب. بأي رقم تتصل؟",options:[{text:"104 فقط.",correct:!1},{text:"115 و122.",correct:!0},{text:"112.",correct:!1},{text:"122 فقط.",correct:!1}],explanation:"115 للحريق والإنقاذ و122 للإسعاف؛ وعند اجتماعهما يُبلَّغ الاثنان."},{question:"في موقع الحادث، أي تصرف من المواطنين مساعد؟",options:[{text:"تصوير فيديو عن قرب لمواقع التواصل.",correct:!1},{text:"إيقاف السيارة قرب الموقع للمشاهدة.",correct:!1},{text:"إعطاء المعلومات للقائد والبقاء خارج الطوق.",correct:!0},{text:"دخول المبنى لإخراج الأغراض.",correct:!1}],explanation:"المعلومات تساعد التقييم والبقاء خارجًا يترك الطريق مفتوحًا؛ والتصوير والدخول يزيدان الخطر."}]},{id:4,code:"OPS-FIR-104",icon:"Flame",accent:"#b91c1c",title:"عمل الإطفاء",subtitle:"كيف يعمل الإطفائيون وما دور المواطنين",summary:"الإطفاء ليس رش الماء فقط: بل يشمل الإنقاذ ووقف الانتشار والتحكم في الدخان والفحص بعد الحريق. يبيّن هذا الدرس بأي ترتيب يعمل الإطفائيون، وما المعدات التي يستخدمونها، وكيف يساعد المواطنون دون أن يعرّضوا أنفسهم للخطر.",blocks:[{heading:"كيف تعيش النار وكيف تنطفئ",body:"تحتاج النار إلى ثلاثة أشياء: الحرارة والوقود والأكسجين، وإلى تفاعل متسلسل يديمها. وكل طرق الإطفاء تزيل أحد هذه العناصر: الماء يخفض الحرارة، والرغوة والمسحوق يعزلان الأكسجين، وإغلاق صمام الغاز أو نقل الوقود يزيل الوقود، وبعض المواد تكسر التفاعل المتسلسل. وهذه المعرفة أساس عمل الإطفاء، لأن المادة المناسبة لحريق قد تكون خطرة على حريق آخر: فالماء على زيت الطبخ المشتعل يسبب انفجارًا، والماء على الأجهزة الكهربائية الموصولة يعرّض لخطر الصعق الكهربائي. لذلك يحدد الإطفائيون نوع الحريق أولًا."},{heading:"ترتيب العمل في موقع الحريق",body:`تعمل فرق الإطفاء بترتيب واضح:

• التقييم: من في الداخل، وأين النار، وما الأخطار.
• الإنقاذ: المحاصَرون هم المهمة الأولى.
• حماية المباني المجاورة كي لا تنتشر النار.
• حصر النار في مكانها ثم إخمادها.
• التحكم في الدخان والحرارة بتنسيق، كي لا يزيد الهواء الجديد النار.
• الفحص بعد الإخماد: البحث عن البؤر الساخنة والنار الخفية داخل الجدران والسقوف.
• حماية الممتلكات من الماء والدخان ثم تسليم الموقع.`},{heading:"معدات الإطفائيين وحمايتهم",body:"يرتدي الإطفائيون ملابس حماية خاصة وخوذًا وقفازات وأحذية مقاومة للحرارة، ويستخدمون داخل الدخان جهاز التنفس المستقل (SCBA)، لأن دخان الحريق مليء بالغازات السامة ولا تُرى فيه العين شيئًا. وتحمل مركبات الإطفاء الماء والمضخات والخراطيم والسلالم ومعدات الإنقاذ. وفي المدن يعتمد الإطفائيون على حنفيات الحريق والطرق المفتوحة. ولا يدخل الإطفائي مبنى مليئًا بالدخان وحده أبدًا؛ بل يعملون في فرق من اثنين أو أكثر ويعرف القائد مكان كل منهم. وهذه المعدات والتدريب تبيّن لماذا لا ينبغي للشخص العادي دخول مبنى يحترق: فمن دونها قد يُفقده الدخان وعيه بأنفاس قليلة."},{heading:"حرائق خاصة: الغاز والكهرباء وزيت الطبخ",body:"بعض الحرائق تحتاج إلى إجراءات خاصة. في حريق الغاز يكون العمل الأول إيقاف الغاز: يغلق شخص مؤهل الصمام فقط إذا كان الوصول إليه آمنًا. ولا يُطفأ لهب غاز لا يمكن إيقافه، لأن الغاز غير المحترق يتجمع وقد ينفجر؛ وعندها يخرج الجميع ويتصلون بالرقم 115. وفي الحريق الكهربائي تُقطع الكهرباء بطريقة آمنة ولا يُرش الماء على الأجهزة الموصولة. وفي حريق زيت الطبخ لا يُستعمل الماء أبدًا؛ بل غطاء معدني أو مطفأة حريق خاصة (Class K) ويُطفأ مصدر الحرارة إن كان ذلك آمنًا. وعند الشك يأخذ الإطفائيون الخطة من القائد."},{heading:"دور المواطن عند الحريق",body:`أفضل ما يقدمه المواطن للإطفائيين:

• اخرج ونبّه الجميع واتصل بالرقم 115 من الخارج.
• أغلق الأبواب خلفك عند الخروج ليبطئ انتشار النار والدخان.
• لا تستخدم مطفأة الحريق إلا إذا كانت النار صغيرة في بدايتها، ومخرجك خلفك، وأنت مدرّب، وتم إبلاغ 115؛ وإن لم تنطفئ فورًا فاخرج.
• ابقَ في الخارج ولا تعد لأخذ الأغراض.
• اترك حنفيات الحريق والطرق مفتوحة ولا توقف السيارات أمام مداخل المباني.
• أعطِ الإطفائيين المعلومات: من ما زال في الداخل، وأين الغاز أو الأسطوانات.`}],steps:[{title:"التقييم",detail:"من في الداخل، وأين النار، ونوعها، والأخطار (غاز، كهرباء، مواد).",critical:!0},{title:"الإنقاذ",detail:"المحاصَرون أولًا؛ يعمل الفريق بأجهزة التنفس وفي أزواج.",critical:!0},{title:"وقف الانتشار",detail:"حماية المباني المجاورة وحصر النار."},{title:"الإخماد",detail:"المادة المناسبة لنوع الحريق؛ ويوقف الغاز أولًا إن كان آمنًا.",critical:!0},{title:"الفحص بعد الإخماد",detail:"البحث عن البؤر الساخنة والنار الخفية كي لا يعود الاشتعال."}],warnings:["لا ترشّ الماء على زيت الطبخ المشتعل: ترتفع النار بعنف وقد تحرقك.","لا تطفئ لهب غاز لا يمكن إيقافه: يتجمع الغاز غير المحترق وقد ينفجر.","لا تعد إلى مبنى يحترق لأخذ الأغراض: الدخان قد يُفقدك الوعي بأنفاس قليلة."],tips:["أغلق الأبواب خلفك عند الخروج.","اترك حنفيات الحريق قرب بيتك مكشوفة ولا تقف أمامها.","اعرف مكان صمام الغاز وقاطع الكهرباء في بيتك لتخبر الإطفائيين."],activity:{prompt:"بدأ حريق في مطبخ الجار وقدر الزيت يشتعل. يريد الجار رش الماء عليه. ماذا تقول؟",options:[{text:"لا ترش الماء؛ إن كان آمنًا ضع الغطاء وأطفئ الموقد، وإلا فاخرج واتصل بالرقم 115.",correct:!0,feedback:"صحيح: الغطاء يعزل الأكسجين؛ والماء يرفع النار."},{text:"رش الماء بسرعة قبل أن تكبر النار.",correct:!1,feedback:"الماء على الزيت المشتعل يتبخر وينثر الزيت المحترق."},{text:"احمل القدر وأخرجه.",correct:!1,feedback:"قد ينسكب الزيت الساخن فيحرقك ويحرق غيرك."},{text:"افتح النافذة ليخرج الدخان.",correct:!1,feedback:"الهواء الجديد يزيد النار."}]},caseStudy:[{prompt:"بدأ حريق في غرفة بمبنى ووصل الدخان إلى الممر. أنت في الطابق الأرضي. ماذا تفعل؟",options:[{text:"أخرج وأنبّه الجميع وأتصل بالرقم 115 من الخارج.",correct:!0,feedback:"صحيح: الدخان في الممر فالمطفأة ليست خيارًا."},{text:"أدخل الممر المليء بالدخان بالمطفأة.",correct:!1,feedback:"الدخان يسد طريق الخروج؛ هذا لا يجتاز فحص ما قبل الاستخدام."},{text:"أبقى في غرفتي وأنتظر دون إبلاغ.",correct:!1,feedback:"إذا كان الخروج ممكنًا فاخرج وأبلغ."}]},{prompt:"وصل الفريق ويسأل القائد هل بقي أحد في الداخل. تعلم أن امرأة مسنة تسكن الطابق الثالث ولم تخرج. ماذا تفعل؟",options:[{text:"أخبر القائد فورًا: الطابق الثالث، وأي جهة، وأنها لا تستطيع المشي بسرعة.",correct:!0,feedback:"صحيح: هذه المعلومة توجّه الإنقاذ."},{text:"أصعد الدرج بنفسي.",correct:!1,feedback:"من دون جهاز تنفس تصبح ضحية أخرى."},{text:"لا أقول شيئًا لأنني لست متأكدًا تمامًا.",correct:!1,feedback:"قل المعلومة حتى لو لم تكن متأكدًا ووضّح ذلك؛ القائد يقرر."}]}],quiz:[{question:"ما أول ما يفعله الإطفائيون في موقع الحريق؟",options:[{text:"التقييم وإنقاذ المحاصَرين.",correct:!0},{text:"حماية الأغراض الثمينة من الماء.",correct:!1},{text:"التحقيق في سبب الحريق.",correct:!1},{text:"كسر كل النوافذ لإخراج الدخان.",correct:!1}],explanation:"الأرواح أولًا: التقييم يبيّن من في الداخل ثم يأتي الإنقاذ؛ الممتلكات والسبب لاحقًا."},{question:"حريق في جهاز غاز والصمام داخل اللهب. ما الصحيح؟",options:[{text:"أطفئ اللهب بالمطفأة ثم أغلق الصمام.",correct:!1},{text:"أغلق الصمام بسرعة بيد مبللة وقطعة قماش سميكة.",correct:!1},{text:"اخرج وأخرج الجميع واتصل بالرقم 115 من الخارج.",correct:!0},{text:"رش الماء على اللهب ليبرد.",correct:!1}],explanation:"لا يُغلق الصمام إلا إذا كان الوصول إليه آمنًا؛ ولا يُطفأ لهب غاز لا يمكن إيقافه خوفًا من الانفجار."},{question:"لماذا يدخل الإطفائيون الدخان بجهاز SCBA؟",options:[{text:"لأن الدخان فيه غازات سامة وقليل الأكسجين.",correct:!0},{text:"لأنه يخفف ثقل الملابس والمعدات عن الإطفائي.",correct:!1},{text:"لأنه يبعد الحرارة عن النار.",correct:!1},{text:"لأنه يدل على طريق الخروج.",correct:!1}],explanation:"الغازات السامة في الدخان تُفقد الوعي بأنفاس قليلة؛ وSCBA يوفر هواءً نقيًّا."},{question:"لماذا يفتح الإطفائيون الجدران والسقوف بعد الإخماد؟",options:[{text:"للعثور على النار الخفية والبؤر الساخنة.",correct:!0},{text:"لزيادة الأضرار للتأمين.",correct:!1},{text:"لإخلاء المبنى أسرع.",correct:!1},{text:"لتجربة معداتهم الجديدة في ظروف حقيقية.",correct:!1}],explanation:"قد تبقى النار داخل الجدران وتعود للاشتعال لاحقًا؛ والفحص يمنع ذلك."},{question:"لديك مطفأة وبدأ حريق صغير في سلة مهملات. أي شرط يلزم قبل الاستخدام؟",options:[{text:"أن تكون النار صغيرة ومخرجك خلفك وتم إبلاغ 115.",correct:!0},{text:"أن تكون وحدك كي لا يعيقك أحد.",correct:!1},{text:"أن يكون الدخان الأسود قد ملأ الغرفة.",correct:!1},{text:"أن تكون النوافذ والأبواب مفتوحة ليدخل هواء نقي كثير.",correct:!1}],explanation:"فحص ما قبل الاستخدام: نار صغيرة في بدايتها، ومطفأة مناسبة، ومخرج خلفك، وتنبيه و115، وتدريب، ودخان لا يسد الطريق؛ وإن غاب أحدها فاخرج."},{question:"أي تصرف من المواطنين يبطئ عمل الإطفائيين؟",options:[{text:"إغلاق الأبواب عند الخروج.",correct:!1},{text:"إيقاف السيارة أمام حنفية الحريق.",correct:!0},{text:"إخبار الفريق بمكان أسطوانات الغاز.",correct:!1},{text:"البقاء خارج المبنى في مكان آمن.",correct:!1}],explanation:"يعتمد الإطفائيون على حنفيات الحريق؛ والسيارة أمامها تضيّع وقتًا ثمينًا. أما التصرفات الأخرى فمساعدة."}]},{id:5,code:"OPS-RES-105",icon:"LifeBuoy",accent:"#0891b2",title:"عمل الإنقاذ: الانهيارات والطرق والمياه والمرتفعات والجبال",subtitle:"كيف يعمل المنقذون وما الذي لا يفعله المواطنون",summary:"الإنقاذ عمل تخصصي يحتاج إلى تدريب ومعدات خاصة. يعرض هذا الدرس خمسة أنواع من الإنقاذ، ويشرح مبادئها المشتركة، ويبيّن كيف يساعد المواطنون دون أن يصبحوا ضحايا جددًا.",blocks:[{heading:"المبادئ المشتركة لكل أنواع الإنقاذ",body:"مهما كان نوع الإنقاذ يعمل المنقذون على المبادئ نفسها. أولًا: سلامة المنقذ، لأن المنقذ المصاب يصبح ضحية أخرى ويُخرج الفريق من العمل. ثانيًا: تقييم الموقع قبل الاقتراب: هل ما زال المبنى يتحرك؟ هل التيار قوي؟ هل هناك كهرباء أو غاز؟ ثالثًا: الوصول إلى المصاب وطمأنته وحمايته من ضرر إضافي ثم إخراجه. رابعًا: تسليمه إلى الإسعافات الأولية والإسعاف. ويتبع المنقذون قاعدة «من الأقل خطرًا إلى الأكثر»: إذا أمكن الإنقاذ بالكلام أو بمدّ شيء فلا يعرّضون أنفسهم للخطر. وهذه القاعدة صحيحة للمواطنين أيضًا."},{heading:"الإنقاذ في الانهيارات",body:"بعد زلزال أو انفجار غاز أو ضعف مبنى قد يُحاصَر أشخاص تحت الجدران والسقوف. تقيّم فرق الإنقاذ البري المبنى أولًا وتحدد المناطق الخطرة، ثم تبحث عن المحاصَرين بالإصغاء والنداء والمعدات الخاصة. وتدعم الجدران والسقوف (Shoring) قبل الدخول تحتها، وتعمل ببطء كي لا تسقط أجزاء أخرى. وفي الانهيارات الكبيرة تحدد الإرشادات الدولية (INSARAG) تنظيم البحث والإنقاذ. يستطيع المواطنون تقديم المعلومات: من كان في المبنى وفي أي غرفة. أما دخول مبنى منهار أو رفع الأنقاض باليد فقد يسبب انهيارًا ثانيًا."},{heading:"الإنقاذ على الطرق وفي المياه",body:"في حوادث المرور يؤمّن المنقذون الموقع أولًا من السيارات الأخرى ويطفئون المحرك ويفحصون خطر الحريق والوقود. ثم يفتحون الأبواب والسقف بمعدات هيدروليكية لإخراج المحاصَر دون تحريك رقبته وظهره. وفي المياه يقوم الإنقاذ على ترتيب «نادِ، مُدّ شيئًا، ارمِ شيئًا، اذهب بالقارب»؛ والسباحة إلى الغريق آخر الحلول وللفرق المدرَّبة فقط. وتستخدم فرق الإنقاذ المائي بدلات الإنقاذ والحبال والقوارب المناسبة، لأن مياه الفيضان قوية وباردة وفيها أشياء خفية. وحتى المياه الضحلة الجارية قد تُسقط الإنسان وتجرف السيارة."},{heading:"الإنقاذ في المرتفعات والجبال",body:"يُحاصَر بعض الناس في أماكن مرتفعة: على سطح أو رافعة أو في بئر أو على منحدر جبلي. والإنقاذ في المرتفعات يحتاج إلى حبال وأحزمة وأجهزة تثبيت وتدريب خاص، لأن أي خطأ قد يسبب السقوط. وفي الجبال قد يحتاج المنقذون إلى وقت طويل للوصول، وقد يتغير الطقس بسرعة ويكون الليل أظلم وأبرد. لذلك على من يذهب إلى الجبل أن يخبر أحدًا بخطته، وأن يحمل الماء وملابس دافئة وهاتفًا مشحونًا، وأن يبقى على الطرق المعروفة. وإذا ضلّ أحد أو أصيب فابقَ في مكانك إن كان آمنًا، وصِف موقعك بوضوح، وأعطِ إشارة ليراك المنقذون."},{heading:"دور المواطن أثناء الإنقاذ",body:`يستطيع المواطنون حماية الأرواح أو زيادة الخطر:

• اتصل بالرقم 115 وصِف المكان بوضوح، وبالرقم 122 إن وُجد مصابون.
• لا تنزل إلى الماء للإنقاذ إن لم تكن مدرَّبًا؛ مُدّ شيئًا أو ارمِ شيئًا يطفو.
• لا تدخل مبنى منهارًا ولا ترفع الأنقاض بيديك.
• لا تحرّك مصاب الحادث إن كان المكان آمنًا، خاصة عند احتمال إصابة الرقبة أو الظهر.
• اترك الطريق مفتوحًا للفرق وابقَ خارج منطقة العمل.
• أعطِ المنقذين معلوماتك: من كان أين ومتى.`}],steps:[{title:"سلامة المنقذ",detail:"افحص الأخطار قبل الاقتراب: الانهيار والماء والكهرباء والغاز والسير.",critical:!0},{title:"التقييم",detail:"كم شخصًا، وأين، وما حالتهم؛ وأي فرق ومعدات تلزم.",critical:!0},{title:"الوصول",detail:"من الأقل خطرًا: النداء ثم المدّ ثم الرمي ثم الوصول بالمعدات.",critical:!0},{title:"الحماية والإخراج",detail:"الطمأنة وحماية الرقبة والظهر عند الحاجة والإخراج بالمعدات المناسبة."},{title:"التسليم",detail:"التسليم إلى الإسعافات الأولية والإسعاف (122) مع ملخص الحادث."}],warnings:["لا تنزل إلى الماء لإنقاذ أحد إن لم تكن مدرَّبًا: كثير من المنقذين غير المدرَّبين يغرقون.","لا تدخل مبنى منهارًا ولا ترفع الأنقاض بيديك: قد يقتلك انهيار ثانٍ مع المحاصَر.","لا تُخرج مصاب الحادث من السيارة إن كان المكان آمنًا: التحريك قد يزيد إصابة الرقبة أو الظهر سوءًا."],tips:["عند الذهاب إلى الجبل أخبر أحدًا بخطتك واحمل هاتفًا مشحونًا.","قرب الماء جهّز شيئًا يطفو أو حبلًا.","إن حوصرت فاطرق على أنبوب أو جدار ليسمعك المنقذون."],activity:{prompt:"سقط طفل في نهر جارٍ بقوة. لست مدرَّبًا على الإنقاذ المائي. ماذا تفعل؟",options:[{text:"أطلب النجدة وأتصل بالرقم 115 وأرمي شيئًا يطفو أو حبلًا.",correct:!0,feedback:"صحيح: الرمي يتيح الوصول دون النزول إلى الماء."},{text:"أقفز إلى الماء فورًا.",correct:!1,feedback:"التيار القوي يجرف المنقذ غير المدرَّب أيضًا؛ فيصبحان ضحيتين."},{text:"أركض على الضفة خلف الطفل دون الاتصال.",correct:!1,feedback:"دون الاتصال لن يأتي الفريق؛ الاتصال والرمي معًا."},{text:"أصوّر فيديو لأريه للمنقذين لاحقًا.",correct:!1,feedback:"التصوير يضيّع وقتًا ثمينًا."}]},caseStudy:[{prompt:"على طريق خارج المدينة انقلبت سيارة والسائق واعٍ بداخلها ويشكو ألمًا في رقبته. لا تسرّب للوقود والسيارة ساكنة. ماذا تفعل؟",options:[{text:"أؤمّن المكان من السيارات الأخرى وأتصل بالرقمين 115 و122 وأتحدث معه دون تحريكه.",correct:!0,feedback:"صحيح: المكان آمن فلا حاجة للتحريك الذي قد يؤذي رقبته."},{text:"أسحبه بسرعة من السيارة.",correct:!1,feedback:"إن كان المكان آمنًا فقد يزيد السحب إصابة الرقبة."},{text:"أعطيه ماءً وطعامًا ليستعيد قوته.",correct:!1,feedback:"هذا لا يساعد رقبته وقد يسبب مشكلة لاحقًا في المستشفى؛ الاتصال والطمأنة أولًا."}]},{prompt:"بعد قليل تظهر رائحة وقود ودخان خفيف من المحرك ولم يصل الفريق بعد. ما الذي يتغير؟",options:[{text:"المكان لم يعد آمنًا؛ إن استطعت بأمان أبعده ببطء مع حماية الرقبة والظهر وأبلغ 115.",correct:!0,feedback:"صحيح: التحريك فقط عندما يصبح المكان غير آمن، مع حماية الرقبة والظهر."},{text:"لا شيء يتغير؛ لن أحركه أبدًا.",correct:!1,feedback:"خطر الحريق جديد؛ بقاؤه قد يهدد حياته."},{text:"أرش الماء على المحرك.",correct:!1,feedback:"الماء على حريق الوقود قد ينشر النار ويقرّبك من الخطر."}]}],quiz:[{question:"أي ترتيب صحيح في الإنقاذ المائي؟",options:[{text:"السباحة ثم الرمي ثم النداء.",correct:!1},{text:"النداء، المدّ، الرمي، ثم القارب.",correct:!0},{text:"القارب ثم السباحة ثم النداء.",correct:!1},{text:"الرمي ثم السباحة ثم المدّ.",correct:!1}],explanation:"من الأقل خطرًا إلى الأكثر؛ والسباحة آخر الحلول وللفرق المدرَّبة فقط."},{question:"لماذا تدعم الفرق الجدران (Shoring) قبل الدخول تحتها؟",options:[{text:"لمنع انهيار ثانٍ.",correct:!0},{text:"ليبدو المبنى أجمل بعد العمل.",correct:!1},{text:"ليعلو صوت المحاصَرين.",correct:!1},{text:"لإنهاء العمل أسرع.",correct:!1}],explanation:"قد يتحرك المبنى المنهار؛ والدعم يحمي المنقذ والمحاصَر."},{question:"عند الذهاب إلى الجبل، أي استعداد يسهّل إنقاذك إن ضللت؟",options:[{text:"إخبار أحد بالخطة وحمل هاتف مشحون.",correct:!0},{text:"الذهاب وحدك في طريق جديد لا يعرفه أحد.",correct:!1},{text:"الانطلاق مساءً لتجنّب حر النهار.",correct:!1},{text:"حمل أقل كمية ماء لتخفيف الحمل.",correct:!1}],explanation:"من يعرف خطتك يبلّغ إن لم تعد، ويعرف المنقذون أين يبحثون."},{question:"انهار مبنى وتسمع صوتًا من تحت الأنقاض. ما أفضل تصرف؟",options:[{text:"أرفع الأنقاض بيدي حتى أصل إليه.",correct:!1},{text:"أحدد المكان للفريق وأتصل بالرقم 115.",correct:!0},{text:"أصعد بالسيارة فوق الأنقاض لأرى أفضل.",correct:!1},{text:"أجمع الناس ليرفعوا الأنقاض معًا.",correct:!1}],explanation:"رفع الأنقاض دون دعم وخطة قد يسبب انهيارًا ثانيًا؛ وتحديد المكان للفريق هو الأفضل."},{question:"طريق تغمره مياه فيضان جارية ضحلة وأنت في سيارة. ماذا تفعل؟",options:[{text:"أعبر بسرعة قبل أن يرتفع الماء.",correct:!1},{text:"أعبر خلف سيارة كبيرة.",correct:!1},{text:"أعود وأبحث عن طريق آخر.",correct:!0},{text:"أتوقف داخل الماء حتى ينحسر.",correct:!1}],explanation:"المياه الضحلة الجارية قد تجرف السيارة وعمقها غير معروف؛ والعودة أسلم."},{question:"أي مبدأ يأتي أولًا في كل أنواع الإنقاذ؟",options:[{text:"السرعة بأي ثمن.",correct:!1},{text:"سلامة المنقذ.",correct:!0},{text:"حماية السيارة والممتلكات.",correct:!1},{text:"التصوير للتقرير.",correct:!1}],explanation:"المنقذ المصاب لا ينقذ أحدًا ويُخرج الفريق من العمل."}]},{id:6,code:"OPS-MED-106",icon:"Ambulance",accent:"#0284c7",title:"الدعم الطبي والتعاون مع خدمة الإسعاف",subtitle:"الإسعافات الأولية في الموقع وتسليم المصاب إلى الإسعاف",summary:"الدفاع المدني والإسعاف (122) حلقتان في سلسلة واحدة. يصل المنقذون إلى المصاب ويقدّمون الإسعافات الأولية ضمن حدود تأهيلهم، ويواصل طاقم الإسعاف العلاج الطبي وينقل المصاب إلى المستشفى. يبيّن هذا الدرس كيف يتم هذا التعاون.",blocks:[{heading:"الدور الطبي للدفاع المدني",body:"يعدّ البروتوكول الأول لاتفاقيات جنيف الخدمات الطبية والإسعافات الأولية من مهام الدفاع المدني. وبحسب دليل الأقسام يقدّم المستجيبون المدرَّبون الإسعافات الأولية ضمن حدود تأهيلهم، وينسّقون مع الخدمات الطبية، ويساندون نقل من يحتاج إلى رعاية. ومعنى ذلك أن المنقذين قد يكونون أول من يصل إلى المصاب تحت الأنقاض أو داخل سيارة منقلبة أو في الماء، قبل أن يتمكن الإسعاف من الاقتراب. وعملهم عندئذ: إبقاء المصاب على قيد الحياة، وحمايته من ضرر إضافي، وإخراجه بأمان. أما العلاج الطبي المتقدم فهو عمل طاقم الإسعاف والمستشفى."},{heading:"الإسعافات الأولية المنقذة للحياة في الموقع",body:`في الموقع يركّز المنقذون والمواطنون المدرَّبون على أعمال منقذة للحياة:

• النزيف الشديد: ضغط مباشر على الجرح، والعاصبة مبكرًا للنزيف المهدد للحياة في الأطراف.
• توقف القلب: الإنعاش القلبي الرئوي (CPR) وجهاز إزالة الرجفان الخارجي الآلي إن وُجد؛ وغير المدرَّب يكتفي بالضغطات الصدرية.
• فاقد الوعي الذي يتنفس طبيعيًّا: وضعية الإفاقة فقط إن لم يُشتبه بإصابة الرقبة أو الظهر أو الورك أو الحوض.
• الحروق: ماء بارد جارٍ لمدة 20 دقيقة.
• الحماية من البرد والطمأنة.

لا يُعطى فاقد الوعي شيئًا عن طريق الفم ولا أي دواء، إلا مساعدة الشخص على استخدام جهازه الموصوف له.`},{heading:"تسليم المصاب إلى الإسعاف",body:"عند وصول الإسعاف يوفّر التسليم القصير الواضح الوقت ويقلل الأخطاء. يذكر المنقذون بهذا الترتيب: ماذا حدث وكيف (سقوط من مرتفع، احتجاز في سيارة، مدة طويلة تحت الأنقاض)؛ والإصابات الظاهرة؛ والعلامات المهمة مثل الوعي والتنفس والنزيف؛ وما قُدّم مثل الضغط أو العاصبة ووقت وضعها؛ وتغيّر الحالة منذ الوصول. وتنتقل هذه المعلومات مع المصاب إلى المستشفى. وإذا تعدد المصابون يحدد القائد مع طاقم الإسعاف ترتيب النقل بحسب شدة الإصابة لا بحسب علوّ الصراخ. أما إجراءات التسليم المحلية فما زالت بحاجة إلى تأكيد رسمي."},{heading:"التنسيق في موقع الحادث",body:"في الحوادث الكبيرة يعمل الدفاع المدني والإسعاف بخطة واحدة. يعمل المنقذون في المنطقة الخطرة ويُخرجون المصابين إلى مكان آمن في الخارج يعمل فيه طاقم الإسعاف. ويجب أن تبقى طرق دخول سيارات الإسعاف وخروجها مفتوحة، ويحدد القائد أماكن وقوفها. وإذا وُجدت مواد خطرة يُزال التلوث عن المصابين قبل التسليم حتى لا يتضرر طاقم الإسعاف والمستشفى. وتبقى غرفة العمليات على اتصال بالخدمات الطبية لتستعد المستشفيات لاستقبال عدد كبير من المصابين. ويتحسن هذا التنسيق بالتمارين المشتركة."},{heading:"دور المواطن",body:`يمكن للمواطن أن يكون الحلقة الأولى:

• اتصل بالرقم 122 للمصابين والمرضى، وبالرقم 115 أيضًا عند وجود حريق أو احتجاز أو انهيار.
• إن كنت مدرَّبًا فقدّم الإسعافات الأولية؛ وإلا فاتبع تعليمات موظف الاتصال.
• لا تحرّك المصاب إن كان المكان آمنًا.
• لا تعطِ أي دواء ولا تعطِ فاقد الوعي شيئًا عن طريق الفم.
• اترك الطريق مفتوحًا للإسعاف ولا تتجمع حول المصاب.
• أخبر طاقم الإسعاف بما رأيت.`}],steps:[{title:"سلامة الموقع",detail:"قبل الاقتراب من المصاب افحص الأخطار واتصل بالرقمين 122 و115.",critical:!0},{title:"إنقاذ الحياة",detail:"أوقف النزيف الشديد بالضغط؛ وإن غاب التنفس فالإنعاش القلبي الرئوي.",critical:!0},{title:"الحماية",detail:"لا تحرّك المصاب إن كان المكان آمنًا؛ احمه من البرد وطمئنه."},{title:"التسليم",detail:"ماذا حدث، والإصابات، والعلامات، وما قُدّم ومتى، وتغيّر الحالة.",critical:!0},{title:"طريق مفتوح",detail:"اترك طريق دخول الإسعاف وخروجه مفتوحًا."}],warnings:["لا تعطِ فاقد الوعي شيئًا عن طريق الفم: قد يختنق.","لا تعطِ المصاب أي دواء إلا مساعدته على استخدام جهازه الموصوف: الدواء الخطأ قد يزيد حالته سوءًا.","لا تستخدم وضعية الإفاقة عند الاشتباه بإصابة الرقبة أو الظهر."],tips:["احضر دورة إسعافات أولية لتساعد في انتظار الإسعاف.","إن وُضعت عاصبة فسجّل وقتها وأخبر الإسعاف.","أرسل شخصًا إلى الطريق ليرشد الإسعاف."],activity:{prompt:"بعد حادث سيارة يرقد شخص فاقد الوعي على الطريق ويتنفس طبيعيًّا، وقد صدمته السيارة بقوة. ماذا تفعل حتى وصول الإسعاف؟",options:[{text:"أؤمّن المكان من السيارات ولا أحرّكه وأراقب تنفسه وأتصل بالرقم 122.",correct:!0,feedback:"صحيح: الصدمة القوية تثير الشك بإصابة الرقبة والظهر فلا تُستخدم وضعية الإفاقة."},{text:"أضعه على جنبه في وضعية الإفاقة.",correct:!1,feedback:"لا تُستخدم وضعية الإفاقة مع الاشتباه بإصابة الرقبة أو الظهر."},{text:"أعطيه ماءً ليستفيق.",correct:!1,feedback:"فاقد الوعي قد يختنق بالماء."},{text:"أنقله بسيارتي إلى المستشفى.",correct:!1,feedback:"النقل دون حماية الرقبة والظهر ودون رعاية طبية قد يزيد الإصابة."}]},caseStudy:[{prompt:"يُخرج المنقذون عاملًا من تحت جدار منهار، وينزف فخذه بشدة، والإسعاف ما زال في الطريق. ما أول عمل؟",options:[{text:"ضغط مباشر على الجرح، وعاصبة إن لم يتوقف النزيف.",correct:!0,feedback:"صحيح: النزيف الشديد يقتل بسرعة ويأتي أولًا."},{text:"رفع ساقه والانتظار.",correct:!1,feedback:"الرفع لا يوقف النزيف؛ الضغط والعاصبة هما الصحيح."},{text:"إعطاؤه مسكّنًا.",correct:!1,feedback:"الدواء ليس من عمل المنقذين ولا يوقف النزيف."}]},{prompt:"وُضعت العاصبة ووصل الإسعاف. ماذا يقولون لطاقم الإسعاف؟",options:[{text:"ملخص الحادث والإصابة ووقت وضع العاصبة وتغيّر الحالة.",correct:!0,feedback:"صحيح: وقت العاصبة مهم جدًّا للمستشفى."},{text:"اسم العامل فقط.",correct:!1,feedback:"الاسم لا يكفي؛ المعلومات الطبية لازمة."},{text:"يفكّون العاصبة ليروا هل توقف النزيف.",correct:!1,feedback:"لا يفك المنقذ العاصبة؛ هذا قرار طبي."}]}],quiz:[{question:"شخص فاقد الوعي لا يتنفس، وبجانبه شخص غير مدرَّب. ما أفضل ما يفعله؟",options:[{text:"يتصل بالرقم 122 ويبدأ الضغطات الصدرية فقط.",correct:!0},{text:"يرش الماء على وجهه وينتظر حتى يستفيق وحده.",correct:!1},{text:"يضعه على جنبه ويتركه.",correct:!1},{text:"ينتظر الإسعاف دون فعل شيء.",correct:!1}],explanation:"بحسب AHA 2025 يكتفي غير المدرَّب بالضغطات الصدرية؛ وكل دقيقة دون ضغط تقلل فرصة النجاة."},{question:"في حادث عدة مصابين. من يُنقل أولًا بالإسعاف؟",options:[{text:"من يصرخ أعلى.",correct:!1},{text:"الأشد إصابة بحسب تقدير الفريق.",correct:!0},{text:"أول من أخرجه الفريق من تحت الأنقاض.",correct:!1},{text:"من حضر أقاربه.",correct:!1}],explanation:"الترتيب بحسب شدة الإصابة؛ وقد يكون الصامت أخطرهم."},{question:"لماذا يُسجَّل وقت وضع العاصبة؟",options:[{text:"ليعرف الأطباء مدة بقائها.",correct:!0},{text:"ليعرف المنقذون متى يفكّونها.",correct:!1},{text:"لكتابة فاتورة الخدمة.",correct:!1},{text:"لأن القانون يطلب كتابته على ورق.",correct:!1}],explanation:"وقت العاصبة مهم للقرار الطبي؛ ولا يفكّها المنقذون أبدًا."},{question:"في حادث مواد خطرة، لماذا يُزال التلوث عن المصابين قبل التسليم؟",options:[{text:"كي لا يتضرر طاقم الإسعاف والمستشفى.",correct:!0},{text:"لالتقاط صور أفضل للتقرير.",correct:!1},{text:"لحفظ ملابسهم لأسرهم.",correct:!1},{text:"ليبقى الإسعاف نظيفًا للمظهر.",correct:!1}],explanation:"قد تنتقل المادة من المصاب إلى الطاقم والمستشفى؛ وإزالة التلوث تمنع ذلك."},{question:"يقول شخص مريض بالقلب إن دواءه معه. ماذا تفعل؟",options:[{text:"أعطيه دواءً آخر من حقيبتي.",correct:!1},{text:"أتصل بالرقم 122 وأساعده فقط على استخدام دوائه الموصوف.",correct:!0},{text:"أعطيه جرعة مضاعفة ليعمل الدواء أسرع ويزول الألم بسرعة.",correct:!1},{text:"آخذ دواءه منه وأحتفظ به حتى يصل الطبيب أو الإسعاف.",correct:!1}],explanation:"المساعدة فقط في استخدام جهاز الشخص أو دوائه الموصوف له؛ ولا نعطي أي دواء آخر."},{question:"يصل الإسعاف إلى زقاق ضيق والناس متجمعون حول المصاب. ما المساعد؟",options:[{text:"إفساح الطريق والابتعاد عن المصاب.",correct:!0},{text:"التصوير لإبلاغ الأسرة.",correct:!1},{text:"حمل المصاب نحو الإسعاف.",correct:!1},{text:"إيقاف السيارات على جانبي الزقاق.",correct:!1}],explanation:"الطريق المفتوح ومساحة العمل يختصران وقت الإسعاف؛ وحمل المصاب من الناس قد يزيد إصابته."}]},{id:7,code:"OPS-EVA-107",icon:"Megaphone",accent:"#7c3aed",title:"إنذار السكان وإيواؤهم وإخلاؤهم",subtitle:"متى تبقى في مكانك ومتى تخرج وكيف تستعد",summary:"الإنذار والإجلاء وإدارة الملاجئ هي المهام الثلاث الأولى في القائمة الدولية لمهام الدفاع المدني. يشرح هذا الدرس كيف يصل الإنذار إلى الناس، والفرق بين البقاء في المكان والإخلاء، وكيف تستعد الأسر.",blocks:[{heading:"الإنذار: من أين وكيف",body:"الإنذار الجيد يمنح الناس وقتًا للتصرف قبل وقوع الخطر. وقد يصل الإنذار بصفارات الإنذار أو بالإذاعة والتلفزيون أو برسائل الهاتف أو بمكبرات الصوت على المركبات أو من باب إلى باب. والإنذار الصحيح يذكر: ما الخطر، وأي منطقة، وماذا يجب أن يُفعل، وإلى متى. أما وسائل الإنذار ومستوياته المستخدمة في محافظة دهوك، مثل أصوات الصفارات ومعانيها، فلم تُؤكَّد رسميًّا بعد؛ لذلك لا يعلّم هذا الدرس أي مستوى أو صوت محدد. والقاعدة: استمع إلى الإنذارات الرسمية من الدفاع المدني والسلطة المختصة، ولا تصدّق شائعات مواقع التواصل قبل التحقق منها."},{heading:"البقاء في المكان أم الإخلاء؟",body:`هناك قراران رئيسيان، وتحدد السلطة المختصة أحدهما بحسب نوع الخطر:

• البقاء في المكان (الاحتماء في الداخل): عندما يكون الخروج أخطر من البقاء، مثل بعض حوادث الغاز أو المواد الخطرة في الخارج. يدخل الناس إلى غرفة داخلية ويغلقون الأبواب والنوافذ ويتابعون التعليمات.
• الإخلاء: عندما يكون البقاء خطرًا، مثل الفيضان أو الحريق الكبير أو المبنى المتصدع. ينتقل الناس عبر الطرق المحددة إلى مكان آمن أو إلى ملجأ.

والقرار ليس قرارك وحدك إذا صدرت تعليمات: اتبع ما تقوله السلطة المختصة. لكن إذا وصلت النار أو المياه إليك فاحمِ حياتك واخرج.`},{heading:"كيف يتم الإخلاء",body:"يبدأ الإخلاء المنظم بخطة: المنطقة الخطرة، وطرق الخروج، ونقاط التجمع، وأماكن الإيواء. تنظّم فرق الدفاع المدني والشرطة حركة السير، ويُخرج أولًا من يحتاج إلى مساعدة مثل كبار السن وذوي الاحتياجات الخاصة والمرضى والأطفال غير المرافقين، ويُعدّ الأشخاص في نقطة التجمع حتى لا يُفقد أحد. وعلى الناس السير في الطرق المحددة لا في طرق مختصرة مجهولة قد تكون فيها مياه أو نار. وبعد الإخلاء لا تكون العودة إلا بعد إعلان رسمي بأن المنطقة آمنة، لأن المباني وأسلاك الكهرباء وأنابيب الغاز قد تكون متضررة."},{heading:"الإيواء",body:"الملجأ مكان آمن يقيم فيه من تم إخلاؤهم مدة قصيرة أو طويلة، مثل مدرسة أو قاعة أو مخيم. وإدارة الملاجئ من مهام الدفاع المدني، وينسّق قسم الإغاثة والإيواء هذا العمل مع المنظمات الإنسانية والجهات الخدمية. وتطلب المعايير الدولية مثل دليل «اسفير» (Sphere) ماءً نظيفًا ومكانًا آمنًا ورعاية صحية وحماية للنساء والأطفال واحترامًا لكرامة الإنسان. وفي الملجأ يتبع الناس تعليمات العاملين، ويحافظون على نظافة المكان، ولا يشعلون النار في الداخل، ويبلّغون عن أي مرض أو خطر. أما مواقع الإيواء الرسمية في دهوك فما زالت بحاجة إلى تأكيد."},{heading:"استعداد الأسرة ودور المواطن",body:`الأسرة المستعدة تتصرف بسرعة وهدوء:

• ضع خطة أسرية: نقطة تجمع، وشخص للتواصل خارج المنطقة، وطرق الخروج.
• جهّز حقيبة طوارئ: ماء، وطعام لا يفسد، والأدوية الموصوفة، ومصباح، وبطاريات، والوثائق المهمة، وملابس دافئة.
• تعرّف إلى جيرانك المسنين وذوي الاحتياجات الخاصة واسأل عنهم.
• عند الإنذار استمع إلى التعليمات الرسمية وتصرف بسرعة.
• لا تسد طريق مركبات الطوارئ، وإذا طُلب الخروج فاخرج فورًا.
• لا تنشر الشائعات؛ شارك المعلومات الرسمية فقط.`}],steps:[{title:"تلقَّ الإنذار",detail:"تحقق من القنوات الرسمية: ما الخطر، وأي منطقة، وماذا تفعل.",critical:!0},{title:"نفّذ القرار",detail:"البقاء في المكان أو الإخلاء بحسب تعليمات السلطة المختصة.",critical:!0},{title:"ساعد المحتاجين",detail:"نبّه وأخرج كبار السن وذوي الاحتياجات الخاصة والأطفال."},{title:"سر في الطريق المحدد",detail:"اذهب إلى نقطة التجمع أو الملجأ وسجّل وجودك."},{title:"العودة بإذن",detail:"لا تعد إلا بعد إعلان رسمي بسلامة المنطقة.",critical:!0}],warnings:["لا تنشر شائعات مواقع التواصل: الإنذار الكاذب قد يسبب الذعر والازدحام على الطرق.","لا تعد بعد الإخلاء دون إعلان رسمي: قد تكون المباني وأسلاك الكهرباء وأنابيب الغاز متضررة.","لا تشعل النار داخل الملجأ: فهناك خطر الحريق والغاز السام."],tips:["ضع حقيبة الطوارئ في مكان سهل قرب الباب.","تدرّبوا على نقطة تجمع الأسرة مع جميع أفرادها.","صوّر وثائقك المهمة واحفظها في مكان آمن."],activity:{prompt:"يقول إنذار رسمي إن مادة خطرة تسربت من مصنع قريب وعلى الناس البقاء في الداخل. تريد أسرتك الخروج بالسيارة. ماذا تقول؟",options:[{text:"نبقى في الداخل ونغلق الأبواب والنوافذ ونتابع التعليمات.",correct:!0,feedback:"صحيح: حين تكون المادة في الخارج قد يضعنا الخروج في الهواء الملوث."},{text:"نخرج بالسيارة بسرعة.",correct:!1,feedback:"هذا يخالف التعليمات الرسمية وقد يقودكم إلى سحابة المادة."},{text:"نفتح النوافذ ليدخل الهواء.",correct:!1,feedback:"فتح النوافذ يُدخل الهواء الملوث."},{text:"نذهب إلى المصنع لنرى ما حدث.",correct:!1,feedback:"هذا يقرّبكم من مصدر الخطر."}]},caseStudy:[{prompt:"يرتفع منسوب النهر بسرعة ويصدر إنذار رسمي بإخلاء حيّك. لديك حقيبة طوارئ وجار مسن يعيش وحده. ماذا تفعل أولًا؟",options:[{text:"أجهّز أسرتي وأنبّه الجار وآخذه معنا.",correct:!0,feedback:"صحيح: من يحتاج المساعدة يُخرج أولًا."},{text:"أنتظر لأرى هل يصل الماء إلى البيت.",correct:!1,feedback:"الانتظار يقلل وقت الخروج وقد تُغلق الطرق."},{text:"أذهب وحدي وأترك الجار للفريق.",correct:!1,feedback:"قد يتأخر الفريق؛ وتنبيه الجار يحمي حياته."}]},{prompt:"على الطريق المحدد، غمرت المياه طريقًا مختصرًا قريبًا والناس يعبرونه. ماذا تفعل؟",options:[{text:"أبقى على الطريق المحدد ولا أدخل الماء.",correct:!0,feedback:"صحيح: المياه الجارية قد تجرف الناس والسيارات."},{text:"أتبع الناس لأنهم عبروا.",correct:!1,feedback:"عبور غيرك لا يعني الأمان؛ قد يرتفع الماء."},{text:"أتوقف وألتقط الصور.",correct:!1,feedback:"التوقف يسد الطريق على الآخرين ويضيّع وقتك."}]}],quiz:[{question:"يقول إنذار رسمي «ابقوا في الداخل». أي تصرف صحيح؟",options:[{text:"إغلاق الأبواب والنوافذ ومتابعة التعليمات.",correct:!0},{text:"الذهاب إلى السوق لشراء الطعام والماء قبل إغلاق المتاجر.",correct:!1},{text:"فتح النوافذ لهواء جديد.",correct:!1},{text:"الذهاب لرؤية مكان الحادث.",correct:!1}],explanation:"البقاء في المكان يعني إغلاق الأبواب والنوافذ والبقاء في الداخل حتى تتغير التعليمات."},{question:"أثناء الإخلاء، من يُخرج أولًا؟",options:[{text:"أصحاب السيارات الكبيرة ليفسحوا الطريق للآخرين بسرعة.",correct:!1},{text:"من يحتاج المساعدة: كبار السن والمرضى والأطفال غير المرافقين.",correct:!0},{text:"أول من يصل إلى نقطة التجمع من الحي كله.",correct:!1},{text:"العاملون في المتاجر لحماية البضائع من السرقة.",correct:!1}],explanation:"من لا يستطيع الخروج وحده بسرعة يحتاج إلى وقت أطول ومساعدة."},{question:"ترى منشورًا يقول «السد سينهار، اهربوا جميعًا». ماذا تفعل؟",options:[{text:"أرسله فورًا إلى كل أصدقائي.",correct:!1},{text:"أتحقق من القنوات الرسمية قبل أي تصرف.",correct:!0},{text:"أهرب بالسيارة دون أن أعرف إلى أين.",correct:!1},{text:"أكتب إلى 115 ليرسلوا المنشور للجميع.",correct:!1}],explanation:"الشائعات الكاذبة تسبب الذعر والازدحام؛ اتبع الإنذارات الرسمية فقط."},{question:"تريد أسرة العودة إلى البيت بعد الإخلاء. متى يصح ذلك؟",options:[{text:"حين تنحسر المياه عن الشارع.",correct:!1},{text:"حين يعود الجيران ويقولون إن كل شيء على ما يرام.",correct:!1},{text:"بعد إعلان رسمي بسلامة المنطقة.",correct:!0},{text:"بعد ليلة واحدة في الملجأ.",correct:!1}],explanation:"قد تكون المباني والكهرباء والغاز متضررة؛ ولا يؤكد السلامة إلا إعلان رسمي."},{question:"ما الذي يجب أن يكون في حقيبة الطوارئ؟",options:[{text:"ماء وأدوية موصوفة ومصباح ووثائق مهمة.",correct:!0},{text:"أجهزة إلكترونية كبيرة وثقيلة لحمايتها.",correct:!1},{text:"أسطوانة غاز للطبخ في الملجأ.",correct:!1},{text:"كل ملابس الأسرة لكل الفصول.",correct:!1}],explanation:"يجب أن تكون الحقيبة خفيفة وفيها الأساسيات؛ والنار والغاز خطران في الملجأ."},{question:"متى يكون الإخلاء أفضل من البقاء في المكان؟",options:[{text:"حين تكون مادة خطرة في الهواء الخارجي.",correct:!1},{text:"حين يقترب فيضان أو حريق كبير من البيت.",correct:!0},{text:"حين ترغب فقط في الخروج.",correct:!1},{text:"حين يقول الإنذار ابقوا في الداخل.",correct:!1}],explanation:"الإخلاء حين يكون البقاء خطرًا كالفيضان والحريق الكبير؛ أما المواد في الهواء فغالبًا البقاء في الداخل بحسب التعليمات."}]},{id:8,code:"OPS-HAZ-108",icon:"Biohazard",accent:"#dc2626",title:"العمل في المواد الخطرة والحوادث الكيميائية والبيولوجية والإشعاعية والنووية",subtitle:"إجراءات الحماية للمواطنين وللفريق",summary:"الوقود والغاز والمواد الكيميائية جزء من الحياة اليومية، وقد يؤدي تسرّبها أو انطلاقها إلى إيذاء كثير من الناس في وقت واحد. ستتعلم في هذا الدرس كيف يعمل الدفاع المدني في حادث مواد خطرة، وما إجراءات الحماية التي تحمي المواطنين.",blocks:[{heading:"ما المقصود بالمواد الخطرة وCBRN؟",body:"المواد الخطرة (HazMat) هي مواد قد تؤذي الإنسان أو الممتلكات أو البيئة إذا خرجت من وعائها: الوقود، وغاز الطبخ والغازات الصناعية، والمواد الكيميائية في المصانع والمزارع، والمواد المنقولة على الطرق. ويرمز CBRN إلى المخاطر الكيميائية والبيولوجية والإشعاعية والنووية؛ ويشمل أحداثًا نادرة لكنها خطيرة قد تؤثر في منطقة كاملة. ويعدّ البروتوكول الأول الكشف عن المناطق الخطرة ووضع العلامات عليها وإزالة التلوث من مهام الدفاع المدني. لا يشرح هذا الدرس خصائص مواد بعينها، بل يعلّم إجراءات الحماية التي تحفظ سلامة المواطنين والفريق، لأن الدقائق الأولى تعتمد على سلوك بسيط وصحيح."},{heading:"علامات حادث المواد الخطرة",body:`كثير من حالات الانطلاق يلاحظها الناس العاديون قبل وصول أي فريق. ومن العلامات:

• سحابة أو بخار أو رذاذ في مكان لا ينبغي أن يكون فيه.
• رائحة غير مألوفة أو حادة، أو صوت صفير من خزان أو أنبوب.
• صهريج أو حاوية متضررة، لا سيما إذا كانت عليها ملصقات تحذير أو لوحات ملوّنة.
• عدة أشخاص يشكون الأعراض نفسها في الوقت نفسه، مثل السعال أو حرقة العينين أو صعوبة التنفس.
• طيور أو حيوانات نافقة دون سبب واضح.

عندما تلاحظ هذه العلامات، لا تقترب لقراءة الملصق أو لمعرفة ما حدث. ابتعد واتصل بالرقم 115.`},{heading:"إجراءات الحماية للمواطنين",body:"هناك إجراءان للحماية ينقذان الأرواح: الإخلاء والاحتماء داخل المبنى. والجهة المختصة هي التي تقرر أيهما يناسب، وأنت تتبع تعليماتها. وحتى ذلك الحين، ابتعد عن مكان الانطلاق نحو الجهة التي تأتي منها الريح، وإلى مكان مرتفع إن أمكن، ولا تمرّ أبدًا عبر سحابة أو مادة منسكبة أو دخان. وإذا طُلب منك الاحتماء داخل المبنى، فادخل وأغلق النوافذ والأبواب، وأطفئ المراوح وأجهزة التكييف، وتابع المعلومات الرسمية. وفي الطوارئ الإشعاعية تبقى النصيحة نفسها: ادخل، وابقَ في الداخل، وتابع الأخبار. ويشرح الدرس 21 من قسم المجتمع هذه الإجراءات بالتفصيل للأسر."},{heading:"كيف يعمل الدفاع المدني في موقع الحادث",body:"يصل الفريق من الجهة التي تهب منها الريح، ويعزل المنطقة أولًا: يُبعد الناس عنها وينقل القريبين إلى مكان آمن. ثم يُقسَّم الموقع إلى مناطق. فلا يدخل المنطقة الساخنة المحيطة بمكان الانطلاق إلا الأعضاء المدرّبون بمعدات الحماية المناسبة. وفي المنطقة الدافئة تُزال الملوثات عن الأشخاص والمعدات، أما المنطقة الباردة فهي مكان القيادة والإسعاف والدعم. ويتعرّف الفريق على المادة من الملصقات ووثائق النقل والسائق أو العاملين في الموقع، ويطلب مشورة المختصين. ويُنسّق قائد الحادث مع الإسعاف (122) والشرطة (104) وجهات الصحة والبيئة، ويقرر مع الجهة المختصة الإخلاء أو الاحتماء."},{heading:"إزالة التلوث وما بعد الحادث",body:"قد يحمل الشخص الذي كان قريبًا من مكان الانطلاق المادة على ملابسه وجلده، وقد ينقلها إلى غيره، ومنهم أسرته والعاملون في المستشفى. اتبع تعليمات الفريق. والنصيحة العامة هي خلع الملابس الخارجية بحذر ووضعها في كيس، وغسل الجلد والشعر بالماء والصابون، وتجنب لمس الوجه والعينين. أخبر الفريق والإسعاف بأنك كنت قريبًا من مكان الانطلاق. وبعد الاستجابة تتولى الجهات المختصة تنظيف الموقع ومراقبة المنطقة، ولا يعود الناس إلا عندما تعلن الجهة المختصة أن المنطقة آمنة. ولا يُستعمل الطعام أو الماء الذي ربما وصلته المادة حتى يعلن المسؤولون سلامته."}],steps:[{title:"التعرّف من بعيد",detail:"لاحظ العلامات (سحابة، رائحة، صهريج متضرر، أشخاص بالأعراض نفسها) دون أن تقترب.",critical:!0},{title:"عزل المنطقة",detail:"أبعد الناس، وانقل القريبين نحو جهة الريح والمكان المرتفع، واتصل بالرقم 115: الموقع وما تراه.",critical:!0},{title:"التعرّف على المادة",detail:"يقرأ الفريق الملصقات والوثائق من مسافة آمنة، ويسأل السائق أو العاملين في الموقع أو المختصين."},{title:"تحديد إجراء الحماية",detail:"بالتنسيق مع الجهة المختصة، يصدر أمر الإخلاء أو الاحتماء ويُبلَّغ المواطنون بوضوح.",critical:!0},{title:"إزالة التلوث والعلاج",detail:"تُزال الملوثات عن المتعرضين في المنطقة الدافئة ثم يُسلَّمون إلى الإسعاف.",critical:!0},{title:"التنظيف والعودة",detail:"تتولى الجهات المختصة التنظيف والمراقبة، ولا يعود الناس إلا عندما تعلن الجهة المختصة أن المنطقة آمنة."}],warnings:["لا تدخل سحابة أو مادة منسكبة أو دخانًا لمساعدة أحد: ستصبح مصابًا آخر؛ اتصل بالرقم 115 وأرشد الفريق.","لا تلمس وعاءً يتسرّب أو مسحوقًا مشبوهًا أو طردًا مجهولًا، ولا تشمّه ولا تنقله لتعرف ما هو.","لا تترك الاحتماء لإحضار سيارة أو أغراض: انتظر التعليمات الرسمية."],tips:["عندما تبلّغ عن انطلاق مادة، اذكر ما تراه واتجاه الريح إن كنت تعرفه.","في العمل، اعرف مكان صحائف بيانات السلامة (SDS) ومن المسؤول عن خطة الموقع.","احتفظ بهاتف مشحون وبجهاز راديو في البيت لتتابع التعليمات الرسمية.","اتفق مع أسرتك على مكان للتجمع إذا صدر أمر بالإخلاء."],activity:{prompt:"انقلب صهريج على طريق قريب من بيتك. هناك سائل ينتشر ورائحة حادة. ماذا تفعل؟",options:[{text:"أقترب لأقرأ الملصق على الصهريج حتى أخبر 115 بدقة عن نوع المادة.",correct:!1,feedback:"غير صحيح: الاقتراب يعرّضك للخطر؛ والفريق يتعرّف على المادة من مسافة آمنة."},{text:"أرشّ السائل بخرطوم الحديقة لتخفيفه.",correct:!1,feedback:"غير صحيح: الماء قد ينشر بعض المواد أو يتفاعل معها؛ هذا عمل الفريق المدرّب."},{text:"أبتعد نحو جهة الريح والمكان المرتفع، وأُبعد الآخرين، وأتصل بالرقم 115 وأذكر الموقع وما أراه.",correct:!0,feedback:"صحيح: المسافة والبلاغ المبكر الواضح أهم إجراءات الحماية."},{text:"أصوّر المشهد من قريب لأنشره تحذيرًا للناس.",correct:!1,feedback:"غير صحيح: البقاء قريبًا للتصوير يعرّض حياتك للخطر وقد ينشر الخوف."}]},caseStudy:[{prompt:"سحابة من تسرّب في مصنع تتجه نحو حي سكني. لم تُصدر الجهة المختصة أمرًا بعد، والريح تدفع السحابة نحو البيوت. ما أفضل نصيحة للسكان؟",options:[{text:"أن يخرج الجميع فورًا بسياراتهم على الطريق الذي يمرّ بجانب المصنع.",correct:!1,feedback:"غير صحيح: قد يمرّ ذلك الطريق عبر السحابة؛ والخروج دون تعليمات قد يكون أخطر."},{text:"أن يبتعدوا عن السحابة، ويدخلوا البيوت إن كانت قريبة، ويغلقوا النوافذ والأبواب، ويتبعوا التعليمات الرسمية.",correct:!0,feedback:"صحيح: إلى أن يصدر الأمر، يحمي الابتعاد عن السحابة والاحتماء في الداخل الناس."},{text:"أن يصعدوا إلى السطح ليروا اتجاه السحابة.",correct:!1,feedback:"غير صحيح: البقاء في الخارج يعرّض الناس للسحابة."}]},{prompt:"أمرت الجهة المختصة بالاحتماء داخل المباني. وصل جار كان قريبًا من المصنع وهو يشكو حرقة في العينين وسعالًا. ماذا ينبغي أن يُفعل؟",options:[{text:"إدخال الجار، وأن يخلع ملابسه الخارجية ويضعها في كيس ويغتسل بالماء والصابون، ثم الاتصال بالرقم 122 وإبلاغهم بأنه كان قريبًا من التسرب.",correct:!0,feedback:"صحيح: هذا يقلل التعرض ويُعلم الإسعاف بما سيواجهه."},{text:"إرسال الجار ماشيًا وحده إلى المستشفى.",correct:!1,feedback:"غير صحيح: المشي في الخارج يُطيل التعرض وقد ينشر المادة."},{text:"فرك عيني الجار بقطعة قماش لتنظيفهما.",correct:!1,feedback:"غير صحيح: الفرك قد ينشر المادة؛ اغسل واتبع تعليمات الفريق الطبي."},{text:"الانتظار حتى يتحسن الجار قبل الاتصال بأحد.",correct:!1,feedback:"غير صحيح: يحتاج الشخص المتعرّض إلى تقييم طبي مبكر."}]}],realCase:"سيناريو توضيحي: اصطدمت شاحنة توصيل تحمل حاويات كيميائية بسيارة قرب مدرسة. رأت معلّمة رذاذًا يتصاعد من الشاحنة وشمّت رائحة حادة. لم تقترب. أبقت الطلاب في الداخل، وأغلقت النوافذ وأطفأت المراوح، ثم اتصلت بالرقم 115 وذكرت الموقع واتجاه الريح. وصل الفريق من جهة الريح، وأغلق الطريق، وحدد المناطق. وأُزيلت الملوثات عن اثنين من المارة كانا قريبين، ثم سُلِّما إلى الإسعاف. ولم يعد الطلاب إلى بيوتهم إلا بعد أن أعلنت الجهة المختصة أن المنطقة آمنة.",quiz:[{question:"ترى سحابة تخرج من صهريج متضرر. في أي اتجاه تتحرك؟",options:[{text:"مع اتجاه الريح، لتدفعك الريح بعيدًا بسرعة أكبر.",correct:!1},{text:"نحو الجهة التي تأتي منها الريح، وإلى مكان مرتفع إن أمكن.",correct:!0},{text:"نحو الصهريج لتنبيه السائق.",correct:!1},{text:"إلى أقرب قبو للاختباء فيه حتى تمرّ السحابة.",correct:!1}],explanation:"التحرك نحو جهة الريح والمكان المرتفع يبعدك عن السحابة؛ فبعض الغازات تتجمع في الأماكن المنخفضة."},{question:"أمرت الجهة المختصة بالاحتماء داخل المبنى. أيّ تصرف خاطئ؟",options:[{text:"إغلاق الأبواب والنوافذ.",correct:!1},{text:"إطفاء المراوح وأجهزة التكييف.",correct:!1},{text:"فتح النوافذ لإدخال هواء نقي.",correct:!0},{text:"متابعة المعلومات الرسمية باهتمام عبر الراديو أو الهاتف.",correct:!1}],explanation:"فتح النوافذ يُدخل الهواء الخارجي والمادة؛ والاحتماء يعني إحكام إغلاق الغرفة."},{question:"من يدخل المنطقة الساخنة في حادث المواد الخطرة؟",options:[{text:"الأعضاء المدرّبون فقط بمعدات الحماية المناسبة.",correct:!0},{text:"أي متطوع من المنطقة يرغب في مساعدة المصابين بسرعة.",correct:!1},{text:"الصحفيون الذين يغطّون الحادث.",correct:!1},{text:"أقارب المصابين في الحادث.",correct:!1}],explanation:"المنطقة الساخنة أخطر مكان؛ ولا يدخلها إلا الأعضاء المدرّبون والمحميّون."},{question:"لماذا تُزال الملوثات عن شخص كان قريبًا من انطلاق مادة كيميائية قبل ذهابه إلى المستشفى؟",options:[{text:"حتى لا يحتاج المستشفى إلى فحصه.",correct:!1},{text:"حتى يتمكن من العودة إلى بيته فورًا.",correct:!1},{text:"لأن إزالة التلوث تُغني عن العلاج الطبي الذي سيتلقاه في المستشفى.",correct:!1},{text:"لأن المادة على الملابس والجلد قد تؤذيه وتؤذي غيره.",correct:!0}],explanation:"إزالة التلوث تقلل الضرر عن الشخص وتمنع انتقال المادة إلى أسرته والعاملين؛ ويبقى العلاج الطبي ضروريًا."},{question:"وجد موظف مسحوقًا مجهولًا يتسرّب من طرد. ما التصرف الأول الصحيح؟",options:[{text:"أن يشمّه بحذر ليعرف ما هو.",correct:!1},{text:"أن يتركه دون لمس، ويُبعد الناس، ويبلّغ عنه.",correct:!0},{text:"أن يجمعه بالمكنسة بحذر في كيس بلاستيكي ويرميه في سلة النفايات.",correct:!1},{text:"أن يحمل الطرد إلى الشارع خارج المبنى.",correct:!1}],explanation:"المواد المجهولة لا تُلمس ولا تُشم ولا تُنقل أبدًا؛ فالمسافة والبلاغ يحميان الجميع."},{question:"ما النصيحة للمواطنين في الطوارئ الإشعاعية؟",options:[{text:"ركوب السيارة والتوجه نحو الموقع.",correct:!1},{text:"البقاء في الخارج حيث الهواء مفتوح.",correct:!1},{text:"الدخول، والبقاء في الداخل، ومتابعة الأخبار.",correct:!0},{text:"انتظار قرار الجيران.",correct:!1}],explanation:"البقاء داخل المبنى يقلل التعرض، والمعلومات الرسمية تخبر الناس بما يفعلونه بعد ذلك."}]},{id:9,code:"OPS-DMC-109",icon:"ClipboardList",accent:"#dc2626",title:"دورة إدارة الكوارث",subtitle:"الوقاية والاستعداد والاستجابة والتعافي",summary:"لا يبدأ عمل الدفاع المدني عند ورود الاتصال، ولا ينتهي عند إخماد الحريق. ستتعلم في هذا الدرس المراحل الأربع لدورة إدارة الكوارث، وكيف تقلل كل مرحلة من ضرر الكارثة التالية.",blocks:[{heading:"لماذا دورة؟",body:"الكارثة ليست لحظة واحدة؛ فهناك عمل قبلها وفي أثنائها وبعدها، وكل جزء يؤثر في الأجزاء الأخرى. وتُقسَّم إدارة الكوارث عادةً إلى أربع مراحل: الوقاية والتخفيف، والاستعداد، والاستجابة، والتعافي. وتُرسم على شكل دائرة لأن الدروس المستفادة في أثناء التعافي تعود إلى الوقاية: فالمجتمع الذي يفهم لماذا أضرّ به الفيضان الماضي يستطيع أن يقلل ضرر الفيضان القادم. ومرحلة الاستجابة هي التي يراها الناس على التلفاز، لكن معظم الأرواح تُنقذ بعمل أُنجز قبل ذلك بوقت طويل، مثل قاعدة بناء، أو قناة تصريف نُظّفت، أو أسرة تدرّبت على خطتها. والدفاع المدني يعمل في المراحل الأربع كلها."},{heading:"الخطر والمخاطر وقابلية التأثر",body:"الخطر (hazard) حدث أو ظرف قد يسبب ضررًا، مثل الفيضان أو الزلزال أو الحريق أو انطلاق مادة كيميائية. ويصبح الخطر كارثة عندما يُخلّ بحياة مجتمع إخلالًا شديدًا ويتجاوز قدرته على المواجهة بموارده الذاتية. وتعتمد مخاطر الكوارث على الخطر نفسه، وعلى من وما يتعرض له، ومدى قابليتهم للتأثر، وقدرتهم على المواجهة. فقد لا يسبب المطر الغزير نفسه أي ضرر في حيّ، ويصبح كارثة في حيّ آخر بُنيت بيوته في مجرى تصريف، وانسدت مصارفه، ولا يعرف أحد فيه إلى أين يذهب. إن تقليل التعرض وقابلية التأثر وبناء القدرات هو جوهر إدارة الكوارث."},{heading:"الوقاية والتخفيف",body:"الوقاية تعني تجنّب إنشاء مخاطر جديدة وإزالة المخاطر القائمة حيثما أمكن: عدم البناء في مجاري السيول، وتطبيق متطلبات السلامة في المباني، وتخزين الوقود والمواد الكيميائية تخزينًا صحيحًا، وتفتيش الأماكن العامة. أما التخفيف فيعني تقليل الضرر عندما لا يمكن منع الخطر: فالزلزال لا يمكن إيقافه، لكن المباني المطابقة لقواعد البناء والأثاث المثبّت بالجدران تقلل الإصابات. والتوعية جزء من الوقاية: فالجمهور الذي يعرف الأخطار يتجنّب كثيرًا من الحوادث. ويشرح الدرس 10 كيف يطبّق الدفاع المدني الوقاية عن طريق التفتيش ومتطلبات السلامة والتوعية العامة."},{heading:"الاستعداد",body:"الاستعداد هو كل ما يُنجز قبل الكارثة لتكون الاستجابة سريعة ومنظمة: خطط الطوارئ، والتدريب وتمارين الإخلاء، وأنظمة الإنذار، ومخازن المعدات والمؤن، والاتفاقات بين الجهات، وخطط الطوارئ وحقائبها لدى الأسر. ويُبقي الدفاع المدني فرقه وآلياته ومعداته جاهزة، ويدرّب منتسبيه، ويشارك في تمارين مشتركة مع الجهات الأخرى. وتُعدّ المؤسسات كالمدارس والمصانع والمستشفيات خططها وتمارينها الخاصة. وتكون الأسرة مستعدة عندما يعرف كل فرد فيها أرقام الطوارئ 115 و122 و104، ونقطة التجمع، وطريق الخروج من البيت."},{heading:"الاستجابة والتعافي",body:"الاستجابة هي العمل الذي يُنجز في أثناء الكارثة وبعدها مباشرة لإنقاذ الأرواح وتقليل الضرر وتلبية الاحتياجات الأساسية للناس: الإنذار والإنقاذ وإطفاء الحرائق والإسعافات الأولية والإخلاء والإيواء، كما ورد في الدروس من 3 إلى 7. أما التعافي فهو العمل الأطول لاستعادة الخدمات والمساكن وسبل العيش والصحة، بما في ذلك الدعم النفسي. والتعافي الجيد لا يُعيد بناء المخاطر نفسها: ففكرة إعادة البناء بشكل أفضل (build back better) تعني إعادة البناء بطريقة أكثر أمانًا وفي أماكن أكثر أمانًا. وعلى المستوى الدولي يوجّه إطار عمل هيوغو (2005–2015) وإطار سنداي للحد من مخاطر الكوارث (2015–2030) الدول؛ ولإطار سنداي أربع أولويات: فهم مخاطر الكوارث، وتعزيز حوكمة المخاطر، والاستثمار في الحد من المخاطر، وتعزيز الاستعداد من أجل استجابة فعالة وإعادة البناء بشكل أفضل في مرحلة التعافي."}],steps:[{title:"تحديد الأخطار",detail:"اكتب الأخطار التي قد تصيب منطقتك أو مكان عملك: الفيضان، الزلزال، الحريق، انطلاق مادة كيميائية أو الطقس الشديد."},{title:"تقييم المخاطر",detail:"اسأل: من وما المعرّض للخطر، ومن الأكثر تأثرًا (الأطفال، كبار السن، الأشخاص ذوو الإعاقة)، وما القدرات المتوافرة."},{title:"تقليل المخاطر",detail:"أزل المخاطر أو قللها حيثما أمكن: الصيانة، ومتطلبات السلامة، والتخزين الصحيح، والتوعية."},{title:"الاستعداد",detail:"اكتب خطة، ودرّب الناس، ونفّذ تمارين الإخلاء، وأبقِ المعدات والمؤن جاهزة."},{title:"الاستجابة وفق الخطة",detail:"عند وقوع الكارثة تأتي الأرواح أولًا: أنذر، وأخلِ أو احتمِ، واتصل بالرقم 115، واتبع قائد الحادث.",critical:!0},{title:"التعافي والتعلّم",detail:"أعد الخدمات بطريقة أكثر أمانًا، وراجع ما نجح وما يجب تغييره، ثم عُد إلى الوقاية."}],warnings:["لا تنتظر الكارثة لتبدأ التخطيط: ففي الدقائق الأولى لا وقت لتقرير من يفعل ماذا.","لا تُعِد البناء في المكان الخطِر نفسه وبالطريقة نفسها دون سؤال الجهة المختصة: فقد تتكرر الكارثة نفسها.","لا تتعامل مع تمرين الإخلاء على أنه إجراء شكلي: فالتمرين الذي لا يؤخذ بجدية يمنح ثقة زائفة."],tips:["تعرّف على أخطار منطقتك؛ فهي نقطة البداية لكل خطة.","بعد كل حادث أو تمرين، اكتب ثلاثة أمور نجحت وثلاثة يجب تحسينها.","أشرك الأشخاص ذوي الإعاقة وكبار السن عند التخطيط، لا بعده.","اجعل خطة الطوارئ لأسرتك قصيرة، وتدرّبوا عليها بين حين وآخر."],activity:{prompt:"غمرت المياه حيًّا مرتين في السنوات الأخيرة. وفي كل مرة رُمِّمت البيوت دون أي تغيير آخر. أي إجراء ينتمي إلى الوقاية والتخفيف؟",options:[{text:"إرسال مزيد من قوارب الإنقاذ في المرة القادمة التي يحدث فيها فيضان.",correct:!1,feedback:"غير صحيح: قوارب الإنقاذ جزء من الاستجابة، ولا تقلل المخاطر."},{text:"تنظيف قنوات التصريف وتوسيعها، ووقف البناء الجديد في مسار السيل، وفق توجيهات الجهة المختصة.",correct:!0,feedback:"صحيح: هذا يقلل الخطر والتعرض قبل الفيضان القادم."},{text:"جمع التبرعات بعد الفيضان القادم.",correct:!1,feedback:"غير صحيح: التبرعات جزء من التعافي وتأتي بعد وقوع الضرر."},{text:"ترميم البيوت مرة أخرى بالطريقة نفسها.",correct:!1,feedback:"غير صحيح: هذا يُعيد بناء المخاطر نفسها بدل تقليلها."}]},caseStudy:[{prompt:"غمر مطر غزير منطقة، والمياه ترتفع في الشوارع. فرق الدفاع المدني في الموقع. أي مرحلة هذه، وما الذي يأتي أولًا؟",options:[{text:"الاستجابة: إنذار الأشخاص المعرّضين للخطر وإخلاؤهم وإنقاذهم.",correct:!0,feedback:"صحيح: في أثناء الكارثة يكون إنقاذ الأرواح أول مهام مرحلة الاستجابة."},{text:"التعافي: تقييم الأضرار في البيوت.",correct:!1,feedback:"غير صحيح: يبدأ التعافي حين لا يبقى أحد في خطر."},{text:"الوقاية: تخطيط قنوات تصريف جديدة.",correct:!1,feedback:"غير صحيح: أعمال الوقاية ضرورية، لكن ليس في أثناء وجود الناس في خطر."}]},{prompt:"بعد شهر انحسرت المياه. ويريد بعض السكان إعادة البناء سريعًا في المكان نفسه الذي دخلت منه المياه. بماذا تنصح الدورة؟",options:[{text:"إعادة البناء بسرعة وبالطريقة نفسها لتعود الحياة إلى طبيعتها.",correct:!1,feedback:"غير صحيح: إعادة بناء المخاطر نفسها تعني أن الكارثة نفسها قد تتكرر."},{text:"ترك المنطقة دون أي خطة.",correct:!1,feedback:"غير صحيح: التعافي يحتاج إلى خطة، لا إلى الترك."},{text:"إعادة البناء وفق خطة الجهة المختصة بطريقة أكثر أمانًا، ومراجعة الدروس المستفادة استعدادًا للفيضان القادم.",correct:!0,feedback:"صحيح: إعادة البناء بشكل أفضل والتعلّم من الدروس يُغلقان الدورة ويعودان إلى الوقاية."},{text:"انتظار الفيضان القادم لمعرفة إن كان خطرًا حقًّا.",correct:!1,feedback:"غير صحيح: لقد أظهر الفيضان الماضي الخطر بالفعل."}]}],realCase:"سيناريو توضيحي: كانت المياه تتجمع كل شتاء في الشوارع المنخفضة لبلدة صغيرة. وفي أحد الأعوام غمرت عاصفة قوية عدة بيوت، وأخلت فرق الدفاع المدني الأسر ليلًا. وفي أثناء التعافي راجع السكان والسلطة المحلية ما حدث، فوجدوا مصارف مسدودة وبيوتًا مبنية في مجرى سيل قديم. فصارت المصارف تُنظَّف قبل كل شتاء، واتُّفق على خطة إنذار مع الدفاع المدني، وتدرّبت الأسر على المكان الذي تذهب إليه. وكانت العاصفة التالية بالقوة نفسها، لكن أحدًا لم يحتج إلى إنقاذ ليلي.",quiz:[{question:"تكتب مدرسة خطة إخلاء وتنفّذ تمرينًا. أي مرحلة من الدورة هذه؟",options:[{text:"الاستجابة.",correct:!1},{text:"التعافي.",correct:!1},{text:"الاستعداد.",correct:!0},{text:"التخفيف بعد الحادث.",correct:!1}],explanation:"الخطط والتمارين التي تُنجز قبل الطوارئ من الاستعداد."},{question:"لماذا تُرسم إدارة الكوارث على شكل دائرة؟",options:[{text:"لأن الدروس المستفادة في التعافي تعود إلى الوقاية.",correct:!0},{text:"لأن الكوارث تأتي في الوقت نفسه من كل عام.",correct:!1},{text:"لأن المراحل الأربع متساوية في المدة.",correct:!1},{text:"لأن الاستجابة هي المرحلة الأولى دائمًا.",correct:!1}],explanation:"تُظهر الدائرة أن كل كارثة تعلّم دروسًا تقلل مخاطر الكارثة التالية."},{question:"يسبب المطر الغزير نفسه كارثة في حيّ ولا يسبب ضررًا في حيّ آخر. ما الذي يفسر الفرق؟",options:[{text:"سوء الحظ فقط.",correct:!1},{text:"كان المطر في ذلك الحيّ أقوى مما توقعته النشرة الجوية.",correct:!1},{text:"المطر يسبب الكوارث دائمًا.",correct:!1},{text:"اختلاف التعرض وقابلية التأثر والقدرات.",correct:!0}],explanation:"تعتمد المخاطر على الخطر وعلى التعرض وقابلية التأثر والقدرات، والناس قادرون على تغييرها."},{question:"لا يمكن منع الزلزال. أي إجراء يُعدّ تخفيفًا؟",options:[{text:"الانتظار حتى ينتهي الزلزال.",correct:!1},{text:"تثبيت الأثاث الثقيل بالجدران والالتزام بقواعد البناء.",correct:!0},{text:"إعادة بناء كل البيوت المتضررة بعد الزلزال بالطريقة نفسها.",correct:!1},{text:"الاتصال بالرقم 115 في أثناء الاهتزاز.",correct:!1}],explanation:"التخفيف يقلل ضرر خطر لا يمكن إيقافه."},{question:"أيّ مما يلي جزء من التعافي؟",options:[{text:"إنقاذ أشخاص محاصرين تحت مبنى منهار في الساعات الأولى.",correct:!1},{text:"تدريب فريق إنقاذ وفحص قواربه قبل موسم الفيضانات.",correct:!1},{text:"إعادة الخدمات ومساعدة الأسر على البناء بأمان أكبر.",correct:!0},{text:"إنذار الناس بقدوم عاصفة.",correct:!1}],explanation:"يستعيد التعافي الخدمات والمساكن وسبل العيش بعد زوال الخطر المباشر."},{question:"ماذا تعني إعادة البناء بشكل أفضل؟",options:[{text:"إعادة البناء بطريقة أكثر أمانًا وفي أماكن أكثر أمانًا.",correct:!0},{text:"إعادة البناء بأسرع طريقة، بالتصميم السابق نفسه وفي المكان نفسه.",correct:!1},{text:"بناء بيوت أكبر من البيوت التي كانت قبل الكارثة.",correct:!1},{text:"ترك المناطق المتضررة خالية إلى الأبد.",correct:!1}],explanation:"تعني استخدام التعافي لتقليل المخاطر، لا لإعادة بنائها."}]},{id:10,code:"OPS-PRV-110",icon:"ClipboardCheck",accent:"#dc2626",title:"الوقاية: التفتيش ومتطلبات السلامة والتوعية العامة",subtitle:"إيقاف الطارئ قبل أن يبدأ",summary:"يمكن منع معظم الحرائق وكثير من الحوادث. ستتعلم في هذا الدرس كيف يمنع الدفاع المدني حالات الطوارئ عن طريق التفتيش ومتطلبات السلامة والتوعية العامة، وما مسؤولية المالكين والمديرين والمواطنين.",blocks:[{heading:"لماذا تأتي الوقاية أولًا",body:"الحريق الذي لا يبدأ أبدًا لا يحتاج إلى سيارة إطفاء، ومخرج الطوارئ المفتوح يوم الحريق ينقذ أرواحًا أكثر من أي عملية إنقاذ. لذلك كانت الوقاية أحد مبادئ عمل الدفاع المدني. وللوقاية ثلاث أدوات رئيسة: تفتيش المباني وأماكن العمل، ومتطلبات السلامة التي يجب على المالكين استيفاؤها، والتوعية العامة التي تعلّم الناس تجنّب الخطر. وفي مديرية دهوك يرتبط هذا العمل بقسم الوقاية والتفتيش والسلامة وقسم الإعلام والتوعية. الوقاية عمل هادئ، ويُقاس نجاحها بحالات الطوارئ التي لا تقع."},{heading:"متطلبات السلامة",body:`متطلبات السلامة هي الشروط التي يجب أن يستوفيها المبنى أو مكان العمل حتى لا يبدأ الحريق أو الطارئ بسهولة، وحتى يتمكن الناس من الخروج بأمان إن بدأ. وتشمل عمومًا:

• مخارج خالية ومُعلَّمة لا تُقفل أبدًا أمام خروج الناس.
• إنارة طوارئ وعلامات مخارج حيث تكون مطلوبة.
• نظام كشف وإنذار حريق مناسب للمبنى.
• مطافئ حريق مناسبة تُفحص وتُصان.
• تخزين صحيح للوقود وأسطوانات الغاز والمواد الكيميائية بعيدًا عن المخارج والحرارة.
• تمديدات كهربائية آمنة دون مقابس محمّلة فوق طاقتها.
• خطة إخلاء وتمارين وشخص مسؤول عن السلامة.

أما المتطلبات الدقيقة والتراخيص والشهادات لكل نوع من الأماكن فيحددها القانون والجهة المختصة، ولا يذكرها هذا الدرس.`},{heading:"كيف يُنفَّذ التفتيش",body:"التفتيش زيارة يقوم بها مفتش مخوَّل للتحقق من استيفاء المكان لمتطلبات السلامة. يستعد المفتش بقراءة الملاحظات السابقة، ثم يتجول في المبنى مع الشخص المسؤول. وتُفحص عناصر سلامة الأرواح أولًا: المخارج والممرات، وأجهزة الإنذار، والمطافئ، وإنارة الطوارئ. ثم يُفحص التخزين والتمديدات الكهربائية والنظافة وسجلات الصيانة والتمارين. وتُسجَّل كل ملاحظة وتُشرح للمالك مع التصحيح المطلوب. وتتحقق زيارة متابعة من تصحيح أوجه القصور. أما الخطر الجسيم على الأرواح، كمخرج مقفل في أثناء مناسبة، فيُبلَّغ به فورًا إلى الجهة المختصة. والمفتش محايد ومهذّب ولا يقبل الهدايا."},{heading:"التوعية العامة",body:"التوعية تعني منح الناس المعرفة التي تجعلهم يتجنبون الخطر ويتصرفون تصرفًا صحيحًا عند وقوعه. ويقوم الدفاع المدني بالتوعية عبر الحملات، وزيارات المدارس وأماكن العمل، والمحاضرات، والرسائل الإعلامية، والأيام المفتوحة. ورسائل التوعية الجيدة قصيرة وبسيطة ومتسقة ومأخوذة من مصادر مخوَّلة، وتستهدف الأكثر عرضة للخطر، كالأطفال وكبار السن والأسر في البيوت القديمة. وتُخطَّط التوعية بحسب الموسم: حرائق التدفئة في الشتاء، والغرق والحر في الصيف. وهذا التطبيق جزء من ذلك العمل. ويُقاس الأثر بتغيّر السلوك، لا بعدد المنشورات."},{heading:"دور المالكين والمديرين والمواطنين",body:"مالك المبنى أو مديره مسؤول عن سلامته كل يوم، لا يوم التفتيش فقط. والتفتيش شراكة لا عقوبة: يشير المفتش إلى الخطر، ويصححه المالك. صحّح أوجه القصور في المدة التي تحددها الجهة المختصة، واحتفظ بسجلات الصيانة، ودرّب موظفيك. والمواطنون يساعدون في الوقاية أيضًا: فلا يغلقون المخارج، ولا يخزنون الوقود في السلالم، ويبلّغون عن الأخطار الجسيمة التي يرونها. وإذا كان الخطر يهدد الأرواح الآن، فاتصل بالرقم 115. واتبع تعليمات الدفاع المدني والجهة المختصة في كل ما يخص التفتيش والتراخيص."}],steps:[{title:"الاستعداد",detail:"اقرأ الملاحظات السابقة ونوع المكان، واتفق على الزيارة مع الشخص المسؤول."},{title:"التجول مع الشخص المسؤول",detail:"زُر كل طابق وكل قسم، بما في ذلك المخازن والسطوح وغرف الأجهزة، برفقة الشخص المسؤول."},{title:"فحص سلامة الأرواح أولًا",detail:"تأتي المخارج والممرات وأجهزة الإنذار والمطافئ وإنارة الطوارئ قبل كل شيء.",critical:!0},{title:"التسجيل والشرح",detail:"دوِّن كل ملاحظة واشرح للمالك ما يجب تصحيحه ولماذا."},{title:"التصرف فورًا عند الخطر الجسيم",detail:"يُبلَّغ عن المخرج المقفل أو أي خطر آخر على الأرواح إلى الجهة المختصة فورًا، ويُصحَّح قبل أن يستخدم الناس المكان.",critical:!0},{title:"المتابعة والتوعية",detail:"تحقق من تصحيح أوجه القصور، واترك للعاملين رسائل سلامة بسيطة."}],warnings:["لا تُقفل مخرج الطوارئ ولا تسدّه أبدًا، حتى لمنع السرقة: ففي الحريق قد يحبس المخرج المقفل الناس ويقتلهم.","لا تُخفِ أوجه القصور ولا تُحضر المعدات من أجل التفتيش فقط: فالخطر يبقى بعد مغادرة المفتش.","لا تقدّم هدايا أو منافع لمفتش: هذا خطأ ويعرّض الأرواح للخطر."],tips:["تفقّد المخارج كل صباح: مفتوحة وخالية ومُعلَّمة.","احتفظ بسجل بسيط لفحص المطافئ والصيانة والتمارين.","اطلب مواد التوعية الرسمية من الدفاع المدني بدل نسخ الرسائل من مواقع التواصل.","خطّط التوعية بحسب الموسم: التدفئة في الشتاء، والماء والحر في الصيف."],activity:{prompt:"يضع صاحب متجر أسطوانات الغاز بجانب المخرج الوحيد لعدم وجود مكان آخر. نبّهه المفتش إلى ذلك. ما أفضل ردّ من صاحب المتجر؟",options:[{text:"إخفاء الأسطوانات في الغرفة الخلفية حتى يغادر المفتش.",correct:!1,feedback:"غير صحيح: الخطر باقٍ، والإخفاء يُبعده عن الأنظار فقط."},{text:"المجادلة بأنه لم يحدث شيء منذ سنوات.",correct:!1,feedback:"غير صحيح: عدم وقوع حوادث سابقة لا يجعل الخطر آمنًا."},{text:"انتظار عقوبة مكتوبة قبل القيام بأي شيء.",correct:!1,feedback:"غير صحيح: الهدف هو السلامة لا تجنب العقوبة، والخطر قائم الآن."},{text:"نقل الأسطوانات إلى مكان آمن جيد التهوية بعيدًا عن المخرج، والسؤال عن طريقة تخزينها الصحيحة.",correct:!0,feedback:"صحيح: تصحيح القصور وتعلّم الطريقة الصحيحة هما غاية التفتيش."}]},caseStudy:[{prompt:"في أثناء تفتيش قاعة مناسبات، وجد المفتش المخرج الخلفي مغلقًا بسلسلة ومقفلًا. ماذا يفعل المفتش أولًا؟",options:[{text:"يدوّنه للزيارة السنوية القادمة.",correct:!1,feedback:"غير صحيح: المخرج المقفل خطر على الأرواح لا يحتمل الانتظار."},{text:"يفتحه بنفسه ويغادر دون تسجيل.",correct:!1,feedback:"غير صحيح: يجب تسجيل الملاحظة وتصحيح سببها."},{text:"يشرح الخطر، ويسجله، ويبلّغ الجهة المختصة حتى يُفتح المخرج قبل استخدام القاعة.",correct:!0,feedback:"صحيح: عناصر سلامة الأرواح أولًا، والخطر الجسيم يُبلَّغ عنه فورًا."}]},{prompt:"يقول المالك إن هناك حفل زفاف الليلة وإن حامل المفتاح غائب. ما النتيجة الصحيحة؟",options:[{text:"يُقام الحفل كما هو مخطط والمخرج مقفل.",correct:!1,feedback:"غير صحيح: قد يُحاصَر مئات الضيوف في حال نشوب حريق."},{text:"يُفتح المخرج ويبقى خاليًا من الأقفال والعوائق قبل دخول أي ضيف، وفق تعليمات الجهة المختصة.",correct:!0,feedback:"صحيح: لا مناسبة تستحق مخرجًا مقفلًا، وتعليمات الجهة المختصة تحدد الخطوات التالية."},{text:"يُطلب من الضيوف استخدام الباب الرئيس فقط.",correct:!1,feedback:"غير صحيح: في الحريق قد يُسدّ الباب الرئيس بالدخان أو اللهب."},{text:"يقبل المفتش دعوة لحضور الحفل.",correct:!1,feedback:"غير صحيح: قبول المنافع يُخلّ بالحياد."}]}],realCase:"سيناريو توضيحي: في زيارة اعتيادية لمصنع صغير، وجدت مفتشة أن المطافئ لم تُفحص منذ مدة طويلة، وأن الكرتون مخزّن في السلم، وأن جهاز الإنذار لا يعمل. شرحت كل ملاحظة للمدير وسجّلتها. فأخلى المدير السلم في اليوم نفسه، ورتّب الصيانة، ودرّب العاملين. وبعد مدة بدأ حريق صغير في إحدى الآلات. فانطلق الإنذار، وخرج العمال عبر السلم الخالي، وأبلغ عامل مدرّب الرقم 115. ولم يُصب أحد.",quiz:[{question:"أيّ مما يلي أفضل مثال على الوقاية؟",options:[{text:"إنقاذ أشخاص عالقين في مصعد.",correct:!1},{text:"تفتيش مبنى وتصحيح مخرج مسدود.",correct:!0},{text:"إطفاء حريق صغير اندلع في مطبخ أحد المطاعم.",correct:!1},{text:"علاج حرق بعد حادث.",correct:!1}],explanation:"الوقاية تزيل الخطر قبل وقوع الطارئ، والبقية استجابة."},{question:"يُقفل مدير مخرج الطوارئ في المناوبات الليلية لمنع السرقة. ما المشكلة؟",options:[{text:"لا مشكلة ما دام المفتاح محفوظًا في مكتب المدير.",correct:!1},{text:"المشكلة في النهار فقط.",correct:!1},{text:"المخرج مهم في أثناء التفتيش فقط.",correct:!1},{text:"قد يُحاصَر الناس إذا نشب حريق ليلًا.",correct:!0}],explanation:"لا تُقفل المخارج أبدًا أمام خروج الناس ما دام في المبنى أحد."},{question:"ما الذي يُفحص أولًا في أثناء التفتيش؟",options:[{text:"المخارج وأجهزة الإنذار والمطافئ.",correct:!0},{text:"لون الجدران والأثاث.",correct:!1},{text:"عدد الزبائن في اليوم.",correct:!1},{text:"نظافة مكتب المدير وترتيب منطقة الاستقبال.",correct:!1}],explanation:"عناصر سلامة الأرواح أولًا لأنها تحدد قدرة الناس على الخروج."},{question:"من المسؤول عن سلامة المبنى كل يوم؟",options:[{text:"مفتش الدفاع المدني وحده.",correct:!1},{text:"الزبائن الذين يزورون المبنى.",correct:!1},{text:"مالك المبنى أو مديره.",correct:!0},{text:"لا أحد حتى يقع حادث.",correct:!1}],explanation:"المفتش يفحص، لكن المالك أو المدير مسؤول عن السلامة كل يوم."},{question:"أيّ رسالة توعية تناسب الشتاء أكثر؟",options:[{text:"كيف تتجنب الغرق في الأنهار.",correct:!1},{text:"كيف تستخدم المدافئ بأمان وتهوّي الغرف.",correct:!0},{text:"كيف تحمي نفسك من الحر الشديد.",correct:!1},{text:"كيف تتصرف بأمان في نزهة عائلية في يوم صيفي حار.",correct:!1}],explanation:"تُخطَّط التوعية بحسب الموسم، وحرائق التدفئة وأبخرتها من مخاطر الشتاء."},{question:"من أين يجب أن تأتي قواعد التفتيش والتراخيص الدقيقة لمكان ما؟",options:[{text:"من منشور على مواقع التواصل.",correct:!1},{text:"من جار يملك متجرًا.",correct:!1},{text:"من رأي المفتش الشخصي.",correct:!1},{text:"من القانون والجهة المختصة.",correct:!0}],explanation:"يحدد القانون والجهة المختصة المتطلبات والتراخيص والمدد."}]},{id:11,code:"OPS-VOL-111",icon:"HeartHandshake",accent:"#dc2626",title:"المتطوعون والمشاركة المجتمعية",subtitle:"المساعدة الآمنة ضمن جهد منظّم",summary:"في الدقائق الأولى من أي طارئ، كثيرًا ما يكون الجيران أول من يصل إلى الموقع. ستتعلم في هذا الدرس كيف يدعم المتطوعون والمجتمع الدفاعَ المدني بأمان، وما الذي ينبغي للمتطوع فعله وما لا ينبغي، وكيف يستعد المجتمع.",blocks:[{heading:"لماذا يهمّ المجتمع",body:"لا يستطيع الدفاع المدني أن يكون في كل مكان في الوقت نفسه. ففي الكارثة الكبيرة تقع حوادث كثيرة معًا، وقد تُغلق الطرق، وقد تحتاج الفرق إلى وقت للوصول. وفي تلك الدقائق يكون القريبون أول من يساعد: يتصلون بالرقم 115، وينبّهون الآخرين، ويرشدون الفريق، ويعتنون بالمصابين في حدود معرفتهم، ويرعون الأطفال وكبار السن. والمجتمع المستعد يضاعف قدرة الدفاع المدني. وتكون المساعدة أنفع ما تكون حين تكون منظمة وآمنة؛ فالمساعدة حسنة النية غير المنظمة قد تسدّ الطرق، وتعرّض المساعدين للخطر، وتصنع طارئًا ثانيًا."},{heading:"ما الذي يستطيع المتطوعون فعله",body:`يستطيع المتطوعون المدرّبون دعم الدفاع المدني بطرق كثيرة لا تتطلب دخول الخطر:

• التوعية في المدارس والمساجد وأماكن العمل والأحياء.
• الإسعافات الأولية في حدود تدريبهم.
• المساعدة في إخلاء من يحتاجون إلى العون.
• دعم مراكز الإيواء: تسجيل الأسر، وتوزيع الماء والطعام والبطانيات.
• رعاية الأطفال وكبار السن والأشخاص ذوي الإعاقة.
• الإمداد: نقل المؤن، وتوجيه الآليات، وإبقاء الطرق مفتوحة.
• الدعم النفسي الأولي: الإصغاء والتهدئة وربط الناس بالخدمات.

أما دخول المباني المحترقة أو المنهارة، والإنقاذ في الماء، والمواد الخطرة، والأجسام المشتبه بأنها متفجرة، فهي عمل المختصين المدرّبين المجهّزين، ولا يقوم بها المتطوع.`},{heading:"قواعد المتطوع في موقع الحادث",body:`المتطوع جزء من فريق، وليس بطلًا يعمل وحده. وهذه القواعد تحفظ سلامة المتطوعين ومن يساعدونهم:

• سجّل نفسك وراجع الشخص المسؤول قبل أي عمل؛ ولا تذهب إلى الحادث من تلقاء نفسك.
• خذ المهمة التي تُكلَّف بها فقط، وابقَ في حدود تدريبك.
• سلامتك أولًا: فالمتطوع المصاب يصبح مصابًا آخر.
• اعمل ضمن ثنائي أو فريق، وأخبر قائد فريقك بمكانك.
• ارتدِ التعريف الذي يُعطى لك، ولا تنتحل أبدًا صفة منتسب الدفاع المدني.
• احترم كرامة المتضررين وخصوصيتهم: لا صور للضحايا ولا نشر لمعلوماتهم.
• انقل المعلومات الرسمية فقط، ولا تنشر الشائعات.`},{heading:"كيف يستعد المجتمع",body:"يستطيع المجتمع الاستعداد قبل الطوارئ بطرق بسيطة. فيتفق الجيران على نقاط التجمع، وعلى وسيلة للتواصل فيما بينهم، وعلى من يتفقد كبار السن والأسر التي لديها أطفال صغار، بموافقتهم. ومن المفيد معرفة السكان الذين لديهم مهارات نافعة، كالممرضين والسائقين والمهندسين، والمباني التي تصلح أماكن للتجمع. ويمكن للمدارس والمراكز المجتمعية استضافة جلسات توعية وتمارين مع الدفاع المدني. ويجري ذلك كله بالتنسيق مع الدفاع المدني والجهة المختصة، حتى تنسجم جهود المجتمع مع الخطة الرسمية ولا تتعارض معها."},{heading:"الانضمام والعناية بالنفس",body:"على من يرغب في التطوع أن يسأل مديرية الدفاع المدني عبر قنواتها الرسمية عن توافر تسجيل المتطوعين وتدريبهم وعن الشروط. ولا يذكر هذا الدرس تلك الشروط لأن المديرية والجهة المختصة هما من يحددانها. ويأتي التدريب قبل العمل الميداني: فالمتطوع الذي تدرّب أكثر أمانًا ونفعًا. وقد يكون التطوع شاقًّا: فالمساعدون يرون المعاناة ويعملون ساعات طويلة. استرح، وكُل، واشرب الماء، وتحدّث مع فريقك أو مع شخص تثق به عما رأيت. وطلب الدعم جزء من إتقان العمل."}],steps:[{title:"التسجيل والمراجعة",detail:"راجع الشخص المسؤول وسجّل نفسك قبل أي عمل؛ ولا تدخل منطقة الحادث وحدك أبدًا.",critical:!0},{title:"استلام المهمة",detail:"أصغِ إلى الإيجاز: مهمتك، وقائد فريقك، والأخطار، وطريقة التواصل."},{title:"التحقق من سلامتك",detail:"تأكد من توافر المعدات والملابس المناسبة للمهمة، ومن أن المكان الذي تُرسَل إليه آمن.",critical:!0},{title:"العمل ضمن فريق وفي حدود التدريب",detail:"اعمل ضمن ثنائي أو فريق، ولا تفعل إلا ما تدرّبت عليه، وتوقف إذا صار الوضع خطرًا.",critical:!0},{title:"الإبلاغ والتسليم",detail:"أخبر قائد فريقك بما فعلت وما رأيت، وسلّم أي شخص أو مهمة تتركها إلى غيرك."},{title:"الراحة والحديث",detail:"استرح وكُل واشرب، وتحدّث عن التجربة مع فريقك في نهاية المناوبة."}],warnings:["لا تدخل حريقًا أو مبنى منهارًا أو مياه فيضان أو منطقة خطرة للمساعدة: انتظر الفريق المدرّب وزوّده بالمعلومات.","لا تصوّر الضحايا ولا تنشر أسماءهم أو إصاباتهم أو أماكنهم: ففي ذلك إساءة لكرامتهم وخصوصيتهم.","لا ترتدِ زيًّا أو شارة لم تُعطَ لك، ولا تقدّم نفسك على أنك من منتسبي الدفاع المدني."],tips:["احضر دورة في الإسعافات الأولية قبل أن تحتاج إليها.","احتفظ بقائمة بكبار السن والأسر التي لديها أطفال صغار في شارعك، بموافقتهم.","اتفق مع جيرانك على نقطة تجمع وعلى من يتفقد من.","اسأل المديرية عبر القنوات الرسمية عن التطوع بدل الحضور إلى موقع الحادث."],activity:{prompt:"بعد زلزال، تُسمع أصوات من بيت منهار جزئيًّا. يريد عدد من الجيران الدخول والحفر. بصفتك متطوعًا مدرّبًا، ماذا تفعل؟",options:[{text:"أُبعد الناس عن المبنى غير المستقر، وأتصل بالرقم 115 وأحدد المكان الدقيق للأصوات، وأساعد في المهام التي يكلفني بها الفريق.",correct:!0,feedback:"صحيح: دخول مبنى غير مستقر عمل المختصين؛ والمعلومات الدقيقة والتنظيم ينقذان الضحايا والمساعدين."},{text:"أقود الجيران إلى الداخل لأن الوقت مهم.",correct:!1,feedback:"غير صحيح: قد تؤدي هزة ارتدادية أو انهيار آخر إلى احتجاز المساعدين أيضًا."},{text:"أبدأ بإزاحة قطع الخرسانة الكبيرة بيدي.",correct:!1,feedback:"غير صحيح: تحريك الأنقاض دون تدريب قد يُسقط بقية المبنى على الضحايا."},{text:"أغادر الموقع لأن المتطوعين لا يستطيعون المساعدة.",correct:!1,feedback:"غير صحيح: يساعد المتطوعون بحفظ النظام وتقديم المعلومات ودعم الأسر."}]},caseStudy:[{prompt:"تصل إلى مركز إيواء أسرٌ تركت بيوتها بسبب فيضان. تريد المساعدة. ماذا تفعل أولًا؟",options:[{text:"أبدأ بتوزيع الطعام من سيارتي على كل من أراه.",correct:!1,feedback:"غير صحيح: التوزيع غير المنسق يسبب الازدحام ويحرم بعض الأسر."},{text:"أراجع مدير مركز الإيواء، وأسجّل نفسي، وآخذ المهمة التي أُكلَّف بها.",correct:!0,feedback:"صحيح: المساعدة أنفع ما تكون حين تُنظَّم تحت إشراف الشخص المسؤول."},{text:"أنشر على مواقع التواصل طالبًا من الجميع الحضور إلى المركز.",correct:!1,feedback:"غير صحيح: حشود بلا مهام تسدّ المركز والطريق."}]},{prompt:"أنت تسجّل الأسر. طلب منك أحد الأقارب تصوير رجل مسنّ مريض ونشر صورته على الإنترنت طلبًا للمساعدة. ماذا تفعل؟",options:[{text:"ألتقط الصورة وأنشرها لأنها قد تجلب المساعدة.",correct:!1,feedback:"غير صحيح: هذا يسيء إلى كرامة الرجل وخصوصيته، والمساعدة تأتي أسرع عبر خدمات المركز."},{text:"أتجاهل الطلب وأتابع التسجيل.",correct:!1,feedback:"غير صحيح: قد يحتاج الرجل إلى رعاية طبية، ويجب نقل حالته."},{text:"أوضّح أن الصور لا تُنشر، وأُبلغ مدير المركز أو الفريق الطبي بحالة الرجل فورًا.",correct:!0,feedback:"صحيح: صون الكرامة وإيصال الرعاية إليه كلاهما من دور المتطوع."},{text:"أعطي الأسرة أدويتي الخاصة له.",correct:!1,feedback:"غير صحيح: لا تُعطى الأدوية إلا عن طريق الفريق الطبي."}]}],realCase:"سيناريو توضيحي: قبل الشتاء حضرت مجموعة من الجيران جلسة توعية مع الدفاع المدني. فاتفقوا على نقطة تجمع، وأعدّوا بموافقة أصحابها قائمة بالسكان المسنّين، ودوّنوا من يستطيع القيادة. وفي ليلة غمر فيها مطر غزير الشارع المنخفض، اتصلوا بالرقم 115، وطرقوا أبواب السكان المسنّين، وجمعوا الجميع في نقطة التجمع. وعندما وصل الفريق سلّمه الجيران القائمة ومكان أسرة لم تُجب. فوصل الفريق إلى تلك الأسرة سريعًا.",quiz:[{question:"وصل متطوع إلى موقع حادث. ما أول ما يفعله؟",options:[{text:"يبدأ المساعدة حيثما دعت الحاجة.",correct:!1},{text:"يلتقط الصور لتوثيق الأضرار.",correct:!1},{text:"يراجع الشخص المسؤول ويسجّل نفسه.",correct:!0},{text:"يبحث عن أخطر مكان ويذهب إليه.",correct:!1}],explanation:"تبدأ المساعدة المنظمة بالتسجيل وتسلّم المهمة من الشخص المسؤول."},{question:"أيّ مهمة تناسب متطوعًا مدرّبًا؟",options:[{text:"تسجيل الأسر وتوزيع الماء في مركز إيواء.",correct:!0},{text:"دخول بيت يحترق للبحث عن أشخاص.",correct:!1},{text:"إبعاد جسم مشتبه بأنه متفجر عن الطريق.",correct:!1},{text:"السباحة في مياه الفيضان للوصول إلى سيارة.",correct:!1}],explanation:"يدعم المتطوعون في أدوار آمنة، أما البقية فعمل مختصين مجهّزين."},{question:"لماذا يجب أن يبقى المتطوع في حدود تدريبه؟",options:[{text:"لأن شهادات التدريب مطلوبة للترقية.",correct:!1},{text:"لأن قائد الفريق لا يحب الأسئلة.",correct:!1},{text:"لأن المتطوعين لا يُسمح لهم بالمساعدة أبدًا.",correct:!1},{text:"لأن العمل خارج التدريب قد يؤذي المتطوع والضحية.",correct:!0}],explanation:"الأفعال غير المدرَّب عليها قد تزيد الإصابات سوءًا وتصنع مصابين جددًا."},{question:"سأل صحفي متطوعًا عن أسماء المصابين. ما الجواب الصحيح؟",options:[{text:"يعطيه الأسماء لأن من حق الناس أن يعرفوا.",correct:!1},{text:"يحيله إلى المتحدث الرسمي.",correct:!0},{text:"يعطيه أسماء المصابين بإصابات خطيرة فقط.",correct:!1},{text:"يشارك صورة بدل الأسماء.",correct:!1}],explanation:"معلومات المتضررين خاصة، والمعلومات الرسمية تصدر عن المتحدث المخوَّل."},{question:"كيف يستعد المجتمع قبل الطوارئ؟",options:[{text:"بالاتفاق على نقاط التجمع وعلى من يتفقد الجيران المسنّين.",correct:!0},{text:"بانتظار أن يتولى الدفاع المدني كل التخطيط.",correct:!1},{text:"بتخزين وقود إضافي في السلم تحسبًا للطوارئ.",correct:!1},{text:"بإخفاء الخطة عن الجيران الجدد.",correct:!1}],explanation:"الترتيبات المشتركة البسيطة تجعل الدقائق الأولى أسرع وأكثر أمانًا."},{question:"بعد عدة مناوبات طويلة لا يستطيع متطوع النوم ويظل يفكر فيما رآه. ما الخطوة الصحيحة؟",options:[{text:"أن يُخفي ذلك ويعمل مدة أطول.",correct:!1},{text:"أن يترك التطوع إلى الأبد دون أن يخبر أحدًا.",correct:!1},{text:"أن يستريح ويتحدث مع شخص يثق به.",correct:!0},{text:"أن يشاهد مقاطع الحادث مرة أخرى.",correct:!1}],explanation:"المساعدون يحتاجون إلى الرعاية أيضًا، والراحة والحديث جزء من إتقان العمل."}]},{id:12,code:"OPS-COO-112",icon:"Network",accent:"#dc2626",title:"العمل مع الجهات الأخرى ونظام قيادة الحوادث",subtitle:"حادث واحد، خطة واحدة، جهات كثيرة",summary:"تحتاج الطوارئ الكبيرة إلى أكثر من جهة. ستتعلم في هذا الدرس كيف يعمل الدفاع المدني مع الإسعاف والشرطة والجهات الأخرى، وكيف يُبقي نظام قيادة الحوادث الجميع يعملون وفق خطة واحدة.",blocks:[{heading:"لا تعمل أي جهة وحدها",body:"في حادث سير خطير مصحوب بحريق، يُطفئ الدفاع المدني الحريق ويحرّر المحاصرين، ويعالج الإسعاف (122) المصابين وينقلهم، وتنظّم الشرطة (104) المرور وتؤمّن الموقع وتحقق في الحادث. وفي الفيضان أو الزلزال تنضم جهات أخرى كثيرة: الخدمات الصحية والمستشفيات، والبلدية بآلياتها الثقيلة وخدمات الماء والطرق، وخدمات الكهرباء والغاز التي تقطع الإمداد، ومنظمات الإغاثة، والجيش أو قوات أخرى عندما تطلبها الجهة المختصة. ولكل جهة مهاراتها ومعداتها ومسؤولياتها القانونية. ولا يُدار الحادث جيدًا إلا عندما تعمل معًا، وتتبادل المعلومات، ولا يعيق بعضها بعضًا."},{heading:"نظام قيادة الحوادث",body:`نظام قيادة الحوادث (ICS) نموذج دولي لتنظيم الاستجابة لأي حادث صغيرًا كان أو كبيرًا. ومبادئه الرئيسة:

• قائد حادث واحد مسؤول عن الحادث كله.
• تسلسل قيادي واضح: كل شخص يرجع إلى مشرف واحد.
• مصطلحات مشتركة ولغة واضحة بدل رموز الجهات.
• نطاق إشراف مناسب: لا يقود المشرف أكثر ممن يستطيع توجيههم بأمان.
• تنظيم مرن يتوسع أو يتقلص بحسب الحادث.
• خطة عمل للحادث بأهداف واضحة.
• مرافق معروفة: مركز قيادة ومنطقة تجمع للموارد الواصلة.
• المساءلة: يسجّل الجميع حضورهم ويُتابَعون حتى مغادرتهم.`},{heading:"هيكل القيادة",body:"في الحادث الصغير يتولى قائد الحادث كل شيء. ومع اتساع الحادث يفوّض القائد المهام. ويدعم طاقم القيادة القائد: فضابط السلامة يراقب الأخطار التي تهدد المستجيبين، وضابط الإعلام يقدّم المعلومات الرسمية لوسائل الإعلام والجمهور، وضابط الارتباط هو نقطة الاتصال مع الجهات الأخرى. ويقود الطاقم العام أربعة أقسام: العمليات تنفّذ العمل الميداني، والتخطيط يجمع المعلومات ويُعدّ الخطة، والإمداد يوفّر المعدات والطعام والوقود والنقل، والمالية والإدارة تتابعان التكاليف والسجلات. ولا يُفعَّل إلا ما يلزم من هذه الأجزاء. وعندما يصل ضابط أعلى رتبة تُسلَّم القيادة بإيجاز، لا بصمت."},{heading:"القيادة الموحدة وتقرير الموقف",body:"عندما تتشارك عدة جهات المسؤولية، تُشكّل قيادة موحدة: يعمل قادتها معًا في مركز قيادة واحد، ويتفقون على مجموعة واحدة من الأهداف وخطة واحدة، مع احتفاظ كل جهة بسلطتها على منتسبيها. ويقوم العمل المشترك على مبادئ بسيطة: التواجد في مكان واحد، والتواصل بوضوح، وتنسيق المهام، وفهم الأخطار معًا، وتقاسم الصورة نفسها عن الحادث. ويساعد تقرير الموقف المنظَّم كل الجهات على فهم الشيء نفسه. ومن الصيغ الشائعة صيغة METHANE: هل أُعلن حادث كبير، والموقع الدقيق، ونوع الحادث، والأخطار، وطرق الوصول، وعدد المصابين ونوع إصاباتهم، وخدمات الطوارئ الموجودة والمطلوبة."},{heading:"المواطنون والمعلومات الرسمية",body:"بالنسبة إلى المواطنين، يعني التنسيق الجيد بضع قواعد بسيطة. اتصل بالرقم الصحيح: 115 للحريق والإنقاذ، و122 للإسعاف، و104 للشرطة؛ وكل منها يحوّل الاتصال عند الحاجة. لا تتجاوز الطوق الأمني أو الشريط: فهو يحميك ويُبقي الطرق مفتوحة للفرق. اتبع تعليمات الشرطة والدفاع المدني في الموقع. وخذ المعلومات من المتحدث الرسمي والقنوات الرسمية فقط، لأن الشائعات تثير الذعر وتعيق العمل. ولا يحدد هذا الدرس أي جهة تقود أي نوع من الحوادث في دهوك؛ فذلك يحدده القانون والجهة المختصة."}],steps:[{title:"تولّي القيادة وتقييم الموقف",detail:"يتولى أول ضابط يصل القيادة، ويفحص الأخطار، ويقرر الموارد اللازمة.",critical:!0},{title:"إرسال تقرير الموقف",detail:"أبلغ بترتيب ثابت مثل METHANE حتى تفهم كل الجهات الصورة نفسها."},{title:"تنظيم الموقع",detail:"اختر مركز القيادة ومنطقة التجمع، وحدّد الطوق الأمني مع الشرطة.",critical:!0},{title:"تشكيل قيادة موحدة",detail:"يجتمع قادة الجهات في مركز القيادة ويتفقون على أهداف واحدة وخطة واحدة."},{title:"توزيع المهام وحصر الأفراد",detail:"أعطِ كل فريق مهمة واضحة ومشرفًا، وتابع كل من يدخل ويخرج.",critical:!0},{title:"التسليم والمراجعة",detail:"سلّم القيادة بإيجاز، وأغلق الحادث بنظام، وراجعه مع كل الجهات."}],warnings:["لا تعمل خارج الخطة: الفريق الذي يتصرف منفردًا قد يعرّض نفسه وغيره للخطر ويُهدر الموارد.","لا تستخدم رموز جهتك على قنوات الراديو المشتركة: استخدم لغة واضحة تفهمها كل الجهات.","لا تتجاوز الطوق الأمني للمشاهدة أو التصوير: فأنت تعرّض نفسك للخطر وتسدّ طرق الفرق."],tips:["تعلّم أسماء أدوار نظام قيادة الحوادث؛ فهي نفسها مهما كان حجم الحادث.","تدرّب على تقارير METHANE في التمارين حتى تصبح تلقائية.","في التمارين المشتركة، تعرّف على منتسبي الجهات الأخرى قبل الطارئ الحقيقي.","دوّن وقت كل قرار وكل تسليم."],activity:{prompt:"اصطدمت شاحنة بحافلة. هناك حريق في المحرك وبعض الركاب محاصرون. وصل الدفاع المدني والإسعاف والشرطة. أي تقسيم للعمل هو الصحيح؟",options:[{text:"تقوم كل جهة بكل شيء، ويعطي أول من يصل الأوامر لمنتسبي الجهات الأخرى.",correct:!1,feedback:"غير صحيح: دون خطة واحدة تكرر الجهات العمل ويعيق بعضها بعضًا."},{text:"تعالج الشرطة المصابين وينظّم الدفاع المدني المرور.",correct:!1,feedback:"غير صحيح: كل جهة تعمل في حدود مهاراتها ومسؤولياتها."},{text:"يُطفئ الدفاع المدني الحريق ويحرّر المحاصرين، ويعالج الإسعاف المصابين وينقلهم، وتنظّم الشرطة المرور والموقع، والجميع تحت قيادة منسقة واحدة.",correct:!0,feedback:"صحيح: كل جهة تؤدي دورها، والقيادة الواحدة تُبقيها على الخطة نفسها."},{text:"ينتظرون مسؤولًا كبيرًا قبل أن يبدأ أحد العمل.",correct:!1,feedback:"غير صحيح: يتولى أول ضابط القيادة فورًا، وتُسلَّم القيادة عند وصول ضابط أعلى رتبة."}]},caseStudy:[{prompt:"في انهيار مبنى، يعطي ضباط من ثلاث جهات أوامر مختلفة للمتطوعين أنفسهم. ما الذي يجب أن يحدث؟",options:[{text:"يشكّل قادة الجهات قيادة موحدة في مركز قيادة واحد، ويتفقون على خطة واحدة وتسلسل أوامر واحد.",correct:!0,feedback:"صحيح: القيادة الموحدة تُنهي تضارب الأوامر مع احتفاظ كل جهة بسلطتها."},{text:"تتولى الجهة الأكثر عددًا العمل وتغادر الجهات الأخرى.",correct:!1,feedback:"غير صحيح: مهارات كل الجهات مطلوبة، والمغادرة تُضعف القدرة."},{text:"يختار المتطوعون الضابط الذي يتبعونه.",correct:!1,feedback:"غير صحيح: هذا يُبقي الفوضى ويعرّض المتطوعين للخطر."}]},{prompt:"يسأل الصحفيون أي مستجيب يلقونه عن عدد الوفيات، وتنتشر أرقام مختلفة. ما الخطوة الصحيحة؟",options:[{text:"تعطي كل جهة أرقامها الخاصة لوسائل الإعلام.",correct:!1,feedback:"غير صحيح: الأرقام المختلفة تصنع البلبلة والشائعات."},{text:"يقدّم ضابط إعلام واحد معلومات موثّقة باسم كل الجهات في أوقات محددة.",correct:!0,feedback:"صحيح: صوت رسمي واحد يعطي الجمهور معلومات متسقة وموثّقة."},{text:"يمنع المستجيبون الصحفيين من العمل.",correct:!1,feedback:"غير صحيح: الإعلام يساعد في إبلاغ الجمهور، ويحتاج إلى مصدر رسمي."},{text:"لا يُقال شيء حتى ينتهي الحادث.",correct:!1,feedback:"غير صحيح: يحتاج الجمهور إلى معلومات السلامة في أثناء الحادث."}]}],realCase:"سيناريو توضيحي: تسبب مطر غزير في انزلاق تربة أغلق طريقًا وألحق أضرارًا ببيتين. تولى أول ضابط من الدفاع المدني القيادة وأرسل تقرير METHANE. أغلقت الشرطة الطريق وحددت الطوق الأمني، وتمركز الإسعاف قرب منطقة التجمع، وأحضرت البلدية الآليات. واجتمع القادة في مركز قيادة واحد واتفقوا على الخطة: الإنقاذ أولًا ثم فتح الطريق. وكان ضابط واحد يُطلع الإعلام كل ساعة. أُنقذ ساكنان، ولم يُصب أي مستجيب، وفُتح الطريق بنظام.",quiz:[{question:"ما الغاية الرئيسة من نظام قيادة الحوادث؟",options:[{text:"تحديد الجهة التي تنال الفضل بعد انتهاء الإنقاذ.",correct:!1},{text:"تنظيم كل المستجيبين ضمن خطة واحدة وتسلسل قيادي واضح.",correct:!0},{text:"الحلول محل عمل الإسعاف.",correct:!1},{text:"تقليل عدد الجهات المسموح لها بالعمل في الموقع.",correct:!1}],explanation:"يمنح النظام كل حادث خطة واحدة وقائدًا واحدًا وخطوط إبلاغ واضحة."},{question:"تتشارك عدة جهات المسؤولية عن حادث. ما الذي يُشكَّل؟",options:[{text:"مراكز قيادة منفصلة لكل جهة.",correct:!1},{text:"لجنة تجتمع بعد الحادث.",correct:!1},{text:"تسلسل تقود فيه الشرطة كل الحوادث.",correct:!1},{text:"قيادة موحدة بخطة واحدة.",correct:!0}],explanation:"في القيادة الموحدة يتفق قادة الجهات على خطة واحدة مع احتفاظ كل جهة بسلطتها."},{question:"أي قسم في نظام قيادة الحوادث يوفّر المعدات والطعام والوقود والنقل؟",options:[{text:"الإمداد.",correct:!0},{text:"العمليات.",correct:!1},{text:"التخطيط.",correct:!1},{text:"المالية والإدارة.",correct:!1}],explanation:"يدعم الإمداد الاستجابة بالموارد، أما العمليات فتنفّذ العمل الميداني."},{question:"لماذا تُستخدم لغة واضحة على قنوات الراديو المشتركة؟",options:[{text:"لأن استخدام الرموز على أي جهاز راديو ممنوع قانونًا.",correct:!1},{text:"لأن أجهزة الراديو لا تنقل الرموز.",correct:!1},{text:"لأن على كل الجهات أن تفهم الرسالة بالطريقة نفسها.",correct:!0},{text:"لأن اللغة الواضحة أقصر دائمًا من الرموز وأسرع.",correct:!1}],explanation:"تستخدم الجهات المختلفة رموزًا مختلفة، واللغة الواضحة تمنع سوء الفهم الخطير."},{question:"وصل ضابط أعلى رتبة إلى حادث جارٍ. كيف تُسلَّم القيادة؟",options:[{text:"بصمت، بمجرد وصول الضابط الأعلى.",correct:!1},{text:"بعد انتهاء الحادث فقط.",correct:!1},{text:"عبر الراديو دون لقاء القائد الحالي.",correct:!1},{text:"بإيجاز وجهًا لوجه عن الموقف والخطة.",correct:!0}],explanation:"يضمن الإيجاز أن يعرف القائد الجديد الموقف والموارد والخطة."},{question:"يرى مواطن حريقًا في بيت وشخصًا مصابًا. أي اتصال هو الصحيح؟",options:[{text:"الرقم 104 فقط، لأن الشرطة تقود كل الحوادث.",correct:!1},{text:"الرقم 115، مع ذكر وجود شخص مصاب.",correct:!0},{text:"الرقم 122 فقط، وترك الحريق.",correct:!1},{text:"انتظار أن يتصل شخص آخر.",correct:!1}],explanation:"يتولى 115 الحريق والإنقاذ وينسّق مع الإسعاف؛ أخبرهم بوجود المصاب."}]},{id:13,code:"OPS-EQP-113",icon:"Truck",accent:"#dc2626",title:"الآليات والمعدات وغرفة العمليات والطوارئ",subtitle:"أدوات العمل والغرفة التي توجّهها",summary:"تعتمد كل استجابة على آليات ومعدات جاهزة، وعلى غرفة عمليات ترسل الفريق المناسب إلى المكان الصحيح. ستتعلم في هذا الدرس الأنواع العامة لآليات الدفاع المدني ومعداته، وكيف تعمل غرفة العمليات، وكيف يستطيع المواطنون المساعدة.",blocks:[{heading:"الجاهزية جزء من الاستجابة",body:"لا يكون الفريق أسرع من آليته، ولا أكثر أمانًا من معداته. فالمضخة التي لا تعمل أو جهاز التنفس ذو الأسطوانة الفارغة قد يكلّفان أرواحًا. لذلك تُفحص الآليات والمعدات في بداية كل مناوبة، وتُنظَّف وتُعاد تعبئتها بعد كل حادث، وتُصان وفق جدول، مع تسجيل كل فحص. وفي مديرية دهوك يدعم قسم الإمداد والمعدات جاهزية الآليات والمعدات وينظّم احتياجات التجهيز والصيانة. ويصف هذا الدرس الأنواع العامة التي تستخدمها أجهزة الدفاع المدني، ولا يذكر آليات أي مديرية بعينها أو معداتها."},{heading:"أنواع الآليات",body:`تستخدم أجهزة الدفاع المدني آليات مختلفة لمهام مختلفة. ومن الأنواع العامة:

• سيارات الإطفاء التي تحمل الماء والمضخة والخراطيم ومعدات الإطفاء.
• صهاريج المياه التي تجلب مزيدًا من الماء حيث يكون الإمداد محدودًا.
• السلالم والمنصات المرتفعة للإنقاذ والإطفاء في الأماكن العالية.
• آليات الإنقاذ المزوّدة بمعدات القطع والرفع والإنارة والمولدات.
• وحدات المواد الخطرة المزوّدة بمعدات الكشف والحماية.
• وحدات الإنقاذ المائي المزوّدة بالقوارب ومعدات الإنقاذ في الماء.
• آليات القيادة والاتصالات للحوادث الكبيرة.
• آليات الدعم والتموين للوقود والطعام والمعدات.

ويعتمد نوع الآليات التي تملكها المديرية وعددها على احتياجاتها ومواردها.`},{heading:"المعدات والحماية الشخصية",body:"يستخدم رجال الإطفاء والإنقاذ معدات الوقاية الشخصية: ملابس مقاومة للنار، وخوذة، وقفازات، وأحذية، وجهاز تنفس حيث يوجد دخان أو غاز سام. وتشمل معدات الإطفاء الخراطيم والفوهات والمطافئ والسلالم. وتشمل معدات الإنقاذ أدوات القطع والفتح الهيدروليكية، ومعدات الرفع، والحبال، والنقالات. وتستخدم الفرق أيضًا حقائب الإسعافات الأولية، وكاميرات التصوير الحراري للعثور على الأشخاص والبؤر الساخنة في الدخان، وكواشف الغاز، وأجهزة الراديو، والإنارة. ولكل قطعة قاعدتان: لا يستخدمها إلا الأعضاء المدرّبون، وتُفحص قبل الاستخدام وبعده. والمعدات التالفة أو المتأخرة صيانتها تُسحب من الخدمة، ولا تُستخدم «هذه المرة فقط»."},{heading:"غرفة العمليات والطوارئ",body:"غرفة العمليات والطوارئ هي المركز العصبي للاستجابة. تتلقى اتصالات 115 والبلاغات، وتسجّلها، وترسل الفرق المناسبة. ويسأل متلقي الاتصال أولًا عن الموقع، ثم عمّا حدث، وعدد المصابين أو المحاصرين، والأخطار الموجودة، ويُبقي المتصل على الخط عند الحاجة. وتتابع الغرفة مكان كل وحدة، وترسل موارد إضافية عندما يتسع الحادث، وتنسّق مع الإسعاف (122) والشرطة (104) والجهات الأخرى، وتُبلغ القيادة. وتحتفظ بسجل للأوقات والقرارات. ولأن الطوارئ قد تقع في أي ساعة، تعمل الغرفة ليلًا ونهارًا."},{heading:"كيف يساعد المواطنون",body:`يستطيع المواطنون أن يجعلوا عمل الآليات وغرفة العمليات أسرع:

• عندما تسمع صفارة الإنذار، تنحَّ جانبًا بأمان ودع الآلية تمرّ، ولا تلحق بها.
• لا تركن سيارتك أمام حنفيات الإطفاء أو مداخل المباني أو الأزقة الضيقة التي تحتاجها سيارة الإطفاء.
• لا تُجرِ أبدًا اتصالات كاذبة: فهي تشغل الخط وقد تُبعد فريقًا عن طارئ حقيقي.
• أبقِ رقم بيتك أو معلمًا واضحًا ظاهرًا، وأعطِ توجيهات دقيقة على الهاتف.
• عندما يصل الفريق، استقبله وزوّده بالمعلومات ثم ابتعد.`}],steps:[{title:"تلقّي الاتصال",detail:"تأخذ غرفة العمليات الموقع أولًا، ثم ما حدث، وعدد الأشخاص، والأخطار.",critical:!0},{title:"إرسال الوحدات المناسبة",detail:"أرسل الآليات والفرق التي يحتاجها الحادث، وأخبر الطواقم بما ينتظرهم."},{title:"القيادة بأمان",detail:"استخدم الأضواء وصفارة الإنذار وفق المسموح، وقُد بحذر: فالآلية التي تتعرض لحادث لا تساعد أحدًا.",critical:!0},{title:"التمركز في الموقع",detail:"اركن الآلية بحيث تكون آمنة من الخطر، ولا تسدّ طريق الوحدات الأخرى، وتستطيع العمل والمغادرة.",critical:!0},{title:"المتابعة والدعم",detail:"تتابع غرفة العمليات الحادث، وترسل موارد إضافية، وتنسّق مع الجهات الأخرى."},{title:"العودة واستعادة الجاهزية",detail:"نظّف الآلية والمعدات وأعد تعبئتها وافحصها، وسجّل أي عطل، وأبلغ بالجاهزية."}],warnings:["لا تسدّ طريق آلية الطوارئ ولا تلحق بها: فكل دقيقة تأخير قد تكلّف حياة، واللحاق بها يعرّضك للخطر.","لا تُجرِ أبدًا اتصالًا كاذبًا بالرقم 115: فقد يُبعد فريقًا عن طارئ حقيقي.","لا تستخدم معدات إنقاذ أو إطفاء لم تتدرّب عليها، حتى لو تُركت بالقرب منك."],tips:["احفظ الأرقام 115 و122 و104 في هاتفك وعلّمها لأسرتك.","اعرف أقرب معلم إلى بيتك لترشد الفريق بسرعة.","اترك حنفيات الإطفاء ومداخل المباني خالية عندما تركن سيارتك.","إن كنت تعمل بالمعدات، فسجّل كل فحص وأبلغ عن الأعطال فورًا."],activity:{prompt:"تقود سيارتك على طريق مزدحم وتسمع صفارة إنذار خلفك. ماذا تفعل؟",options:[{text:"أضغط على المكابح بقوة وأتوقف في وسط المسار.",correct:!1,feedback:"غير صحيح: التوقف المفاجئ في المسار قد يسبب حادثًا، ويبقى عائقًا أمام الآلية."},{text:"أعطي إشارة، وأتنحى جانبًا بأمان حين أستطيع، وأدع الآلية تمرّ، ثم لا ألحق بها.",correct:!0,feedback:"صحيح: فتح طريق آمن بسرعة يساعد الفريق على الوصول دون التسبب في حادث آخر."},{text:"أزيد سرعتي لأبقى أمام آلية الطوارئ.",correct:!1,feedback:"غير صحيح: السرعة خطرة ولا تفتح الطريق."},{text:"ألحق بها عن قرب لأعبر الزحام أسرع.",correct:!1,feedback:"غير صحيح: اللحاق بآلية الطوارئ خطر وقد يسدّ موقع الحادث."}]},caseStudy:[{prompt:"متصل بالرقم 115 يصرخ: «حريق، تعالوا بسرعة!» عمّ يسأل متلقي الاتصال أولًا؟",options:[{text:"عن الموقع الدقيق للحريق.",correct:!0,feedback:"صحيح: دون الموقع لا يمكن إرسال أي فريق، حتى لو انقطع الخط."},{text:"عن الاسم الكامل للمتصل وعمره.",correct:!1,feedback:"غير صحيح: الاسم مفيد، لكن الموقع يأتي أولًا."},{text:"عن سبب الحريق.",correct:!1,feedback:"غير صحيح: يُحقَّق في السبب لاحقًا، وهو لا يحدد الاستجابة."}]},{prompt:"في الوقت نفسه، يُبلَّغ عن حادث سير فيه محاصرون وعن حريق نفايات صغير، ولا تتوافر إلا وحدات قليلة. ماذا تفعل غرفة العمليات؟",options:[{text:"ترسل الوحدات إلى الاتصال الذي ورد أولًا.",correct:!1,feedback:"غير صحيح: ترتيب الاتصالات لا يحدد الأولوية، بل الخطر على الأرواح."},{text:"ترسل كل الوحدات إلى حريق النفايات لأنه أقرب.",correct:!1,feedback:"غير صحيح: المسافة وحدها لا تحسم الأمر، والمحاصرون هم الأولوية."},{text:"تعطي الأولوية للمحاصرين، وترسل ما يلزم لكل حادث، وتطلب موارد إضافية وفق الخطة.",correct:!0,feedback:"صحيح: الخطر على الأرواح يحدد الأولوية، والغرفة تطلب الدعم عند نقص الموارد."},{text:"تنتظر انتهاء أحد الحادثين قبل الرد على الآخر.",correct:!1,feedback:"غير صحيح: كلاهما يحتاج إلى استجابة، والغرفة تدير الأولويات والدعم."}]}],realCase:"سيناريو توضيحي: في وقت متأخر من الليل اتصل ساكن بالرقم 115 بشأن دخان يخرج من متجر تحت شقته. سألته متلقية الاتصال أولًا عن الموقع وعن معلم قريب، ثم هل في الداخل أحد، وأبقته على الخط. وأرسلت سيارة إطفاء وآلية إنقاذ، وأبلغت الإسعاف. وتنحّى السائقون على الطريق الرئيس جانبًا، وكان الزقاق الضيق خاليًا من السيارات المركونة، فوصلت سيارة الإطفاء إلى المبنى بسرعة. وأُخمد الحريق، وفي المركز نظّف الطاقم المعدات وأعاد تعبئتها وأبلغ بجاهزيته.",quiz:[{question:"لماذا تُفحص الآليات والمعدات في بداية كل مناوبة؟",options:[{text:"لأن القانون يشترط فحص الطلاء.",correct:!1},{text:"لتحديد أي طاقم يقود أي آلية.",correct:!1},{text:"لعدّ الآليات التي تملكها المديرية.",correct:!1},{text:"ليُكتشف العطل قبل الطارئ لا في أثنائه.",correct:!0}],explanation:"المضخة أو جهاز التنفس الذي يتعطل في أثناء الحادث قد يكلّف أرواحًا."},{question:"عمّ يسأل متلقي الاتصال في غرفة العمليات أولًا؟",options:[{text:"الموقع.",correct:!0},{text:"عمر المتصل.",correct:!1},{text:"سبب الحريق.",correct:!1},{text:"اسم المالك.",correct:!1}],explanation:"دون الموقع لا يمكن إرسال أي فريق، والتفاصيل الأخرى تأتي بعده."},{question:"على فريق أن يصل إلى أشخاص محاصرين في الدخان في طابق علوي. أي معدّة تساعده على العثور على الناس في الدخان الكثيف؟",options:[{text:"صهريج مياه متوقف عند المدخل.",correct:!1},{text:"مولّد كهربائي متنقل للإنارة.",correct:!1},{text:"كاميرا تصوير حراري.",correct:!0},{text:"نقالة قابلة للطي للمصابين.",correct:!1}],explanation:"تُظهر كاميرات التصوير الحراري الأشخاص والبؤر الساخنة عبر الدخان."},{question:"تأخرت صيانة جهاز تنفس لكنه يبدو سليمًا. ما القرار الصحيح؟",options:[{text:"استخدامه هذه المرة لأن الوقت ضيق.",correct:!1},{text:"سحبه من الخدمة حتى تتم صيانته.",correct:!0},{text:"إعطاؤه لمتطوع ليستخدمه.",correct:!1},{text:"استخدامه في المهام القصيرة فقط.",correct:!1}],explanation:"تُسحب المعدات المتأخرة صيانتها من الخدمة، فتعطلها داخل الدخان قد يكون قاتلًا."},{question:"أي تصرف من المواطنين يساعد سيارة الإطفاء على الوصول إلى المبنى بأسرع وقت؟",options:[{text:"إبقاء الأزقة الضيقة ومداخل المباني خالية من السيارات المركونة.",correct:!0},{text:"اللحاق بسيارة الإطفاء لإرشادها إلى الطريق.",correct:!1},{text:"الاتصال بالرقم 115 عدة مرات متتالية لاستعجال الفريق.",correct:!1},{text:"الوقوف وسط الطريق للتلويح للطاقم وإرشاده باليد.",correct:!1}],explanation:"الطريق الخالي يتيح للآلية الوصول والتجهز بسرعة، والاتصالات المتكررة تشغل الخط."},{question:"اتصل شخص بالرقم 115 على سبيل المزاح. ما الضرر الرئيس؟",options:[{text:"تزداد فاتورة هاتفه.",correct:!1},{text:"يتعين على غرفة العمليات كتابة تقرير.",correct:!1},{text:"قد يُبعَد فريق عن طارئ حقيقي.",correct:!0},{text:"قد يُعرَف من صوته.",correct:!1}],explanation:"الاتصالات الكاذبة تُبعد الخط والفرق عمن يحتاجونها حقًّا."}]},{id:14,code:"OPS-CAR-114",icon:"Award",accent:"#dc2626",title:"أن تكون منتسبًا للدفاع المدني: الأخلاق والسلامة واللياقة والمسار المهني",subtitle:"الإنسان وراء الزي الرسمي، وخلاصة المقرر",summary:"يعتمد عمل الدفاع المدني على أشخاص أمناء وآمنين ولائقين ومدرّبين جيدًا. ستتعلم في هذا الدرس قيم منتسب الدفاع المدني، وثقافة السلامة، واللياقة والصحة، ومسارات التدريب والعمل، وتراجع المقرر كله عن عمل الدفاع المدني.",blocks:[{heading:"القيم والأخلاق",body:`منتسب الدفاع المدني يخدم الجميع. فالناس يفتحون بيوتهم للفريق في أسوأ لحظات حياتهم، ويجب أن يثقوا به ثقة تامة. والقيم الأساسية هي:

• الإنسانية: تُقدَّم المساعدة لحماية الحياة وتخفيف المعاناة.
• الحياد: تذهب المساعدة إلى الجميع بحسب الحاجة، دون تمييز.
• النزاهة: لا هدايا ولا رشى، ولا يؤخذ أي شيء من موقع الحادث أبدًا؛ وتُسلَّم الممتلكات التي يُعثر عليها وفق الإجراءات.
• احترام الكرامة والخصوصية: لا صور للضحايا ولا نشر للمعلومات الشخصية.
• الانضباط: تُنفَّذ الأوامر المشروعة ويُحترم التسلسل القيادي.
• المسؤولية عن الزي والشارة: لا يُستخدمان إلا للخدمة، في أثناء الدوام وخارجه، بما في ذلك على مواقع التواصل.`},{heading:"ثقافة السلامة",body:"المنتسب المصاب لا يستطيع إنقاذ أحد، ويصبح مصابًا آخر على الفريق. لذلك فالسلامة جزء من كل مهمة، لا أمر إضافي. يرتدي المنتسبون معدات الوقاية كاملة، ويعملون ضمن ثنائيات، ولا يدخلون منطقة خطرة منفردين أبدًا، ويسجّلون دخولهم وخروجهم ليعرف القائد دائمًا من يوجد وأين، ويوقفون العمل حين تصبح الظروف شديدة الخطر. وفي العمليات الطويلة أو الحارّة يتناوب المنتسبون: يستريحون، ويشربون الماء، ويأكلون، ويُفحصون قبل العودة إلى العمل. ويُبلَّغ عن الحوادث الوشيكة والإصابات الصغيرة، لأن كل بلاغ يساعد على منع حادث خطير. والقيادة الآمنة لآليات الطوارئ جزء من هذه الثقافة نفسها."},{heading:"اللياقة والصحة",body:"عمل الدفاع المدني شاق بدنيًّا: يحمل المنتسبون معدات ثقيلة، ويصعدون السلالم في الحر والدخان، ويعملون ساعات طويلة بأجهزة التنفس. وتساعد الرياضة المنتظمة والغذاء الصحي والنوم الكافي وترك التدخين المنتسبين على أداء هذا العمل بأمان، وتجري الفحوص الطبية وفق أنظمة المؤسسة. والعقل يحتاج إلى العناية أيضًا. فالمنتسبون يرون الإصابات والموت، والضغط النفسي بعد حادث صعب ردّ فعل إنساني طبيعي. والحديث مع الزملاء أو المشرف أو مختص، وملاحظة التغيرات في النوم أو المزاج أو الانفعال، علامات قوة لا ضعف. وتحتاج الأسر أيضًا إلى الدعم، لأن نظام المناوبات والخطر يؤثران فيها كذلك."},{heading:"التدريب والمسارات المهنية",body:"يبدأ كل منتسب بتدريب أساسي، ويواصل التدريب طوال خدمته، لأن المهارات تضعف والأساليب تتغير. ويقدّم عمل المديرية مسارات كثيرة تقابل أقسامها: الإطفاء، والإنقاذ البري، والإنقاذ المائي، والمواد الخطرة، والإسعافات الأولية، وغرفة العمليات والطوارئ، والوقاية والتفتيش والسلامة، والإعلام والتوعية، والتعليم والتدريب، والإمداد والمعدات، والإغاثة والإيواء، والإدارة. ويمكن لذوي الخبرة أن يصبحوا مدرّبين وقادة. ويُقدَّم طلب التوظيف عبر الإعلانات الرسمية للدفاع المدني، وتحدد المديرية شروط العمر والتعليم والصحة والاختبارات. ولا يذكر هذا الدرس تلك الشروط؛ فاسأل المديرية عن المعلومات المحدّثة."},{heading:"خلاصة المقرر",body:"تتبّع هذا القسم عمل الدفاع المدني من غايته إلى الأشخاص الذين ينفّذونه. فقد شرح الدرسان 1 و2 المهمة والأساس القانوني وتنظيم المديرية. وتتبّعت الدروس من 3 إلى 7 الاستجابة: دورة 115، والإطفاء، والإنقاذ، والدعم الطبي، والإنذار والإيواء والإخلاء. وتناول الدرسان 8 و9 المواد الخطرة ودورة إدارة الكوارث. وعرض الدرسان 10 و11 الوقاية ودور المتطوعين والمجتمع. وشرح الدرسان 12 و13 التنسيق مع الجهات الأخرى، والآليات والمعدات وغرفة العمليات. وتسري في الدروس كلها خمس رسائل: الحياة أولًا، وسلامة الفريق أولًا، والعمل منظّم تحت قيادة واحدة، والوقاية تحمي أرواحًا أكثر من الاستجابة، والمواطنون شركاء في كل مرحلة."}],steps:[{title:"الحضور بلياقة وجاهزية",detail:"احضر إلى مناوبتك مرتاحًا، وافحص معدات الوقاية، وأبلغ عن أي مشكلة صحية.",critical:!0},{title:"تسجيل الحضور والاستماع إلى الإيجاز",detail:"اعرف فريقك ومشرفك ومهامك قبل أن تبدأ."},{title:"العمل بأمان ضمن الفريق",detail:"ارتدِ معدات الوقاية كاملة، واعمل ضمن ثنائي، وأبقِ القائد على علم بمكانك.",critical:!0},{title:"معاملة الجميع باحترام",detail:"اخدم كل شخص بحياد، واحمِ خصوصيته، وسلّم أي ممتلكات تعثر عليها."},{title:"الراحة واستعادة القوة",detail:"في العمليات الطويلة خذ دورك في التناوب: استرح واشرب وكُل، وافحص نفسك قبل العودة."},{title:"الإبلاغ والتعلّم والعناية بالنفس",detail:"أبلغ عن الإصابات والحوادث الوشيكة، وشارك في المراجعة، وتحدّث مع أحد إن بقي الحادث عالقًا في ذهنك."}],warnings:["لا تقبل الهدايا أبدًا ولا تأخذ أي شيء من موقع الحادث: فذلك يهدم ثقة الناس بالدفاع المدني ويُعدّ مخالفة جسيمة.","لا تنزع معدات الوقاية في منطقة خطرة لتعمل أسرع: فنَفَس واحد من الدخان أو حرق واحد قد يُنهي خدمتك.","لا تُخفِ الإرهاق أو الإصابة أو الضيق النفسي: فالمنتسب الذي لا يستطيع العمل بأمان يعرّض الفريق كله للخطر."],tips:["تدرّب قليلًا كل يوم: السلالم والحمل والتحمّل تساعدك في العمل الحقيقي.","افحص معدات الوقاية كأن حياتك تعتمد عليها، لأنها كذلك.","واصل التعلّم: اطلب التدريب في تخصص ثانٍ حين تستطيع.","اتفق مع زميل على أن يطمئن كل منكما على الآخر بعد الحوادث الصعبة."],activity:{prompt:"في أثناء إطفاء حريق في متجر، رأى منتسب نقودًا على الأرض. قال له زميل: «لن يلاحظ أحد، خذ بعضها.» ما التصرف الصحيح؟",options:[{text:"أن يأخذ قليلًا ما دام المتجر متضررًا على أي حال.",correct:!1,feedback:"غير صحيح: أخذ الممتلكات من موقع الحادث سرقة ويهدم الثقة بالخدمة كلها."},{text:"أن يتركها على الأرض ولا يقول شيئًا.",correct:!1,feedback:"غير صحيح: قد تضيع النقود أو يأخذها غيره، ويجب تسليمها وفق الإجراءات."},{text:"أن يعطيها للزميل ليتصرف بها لاحقًا.",correct:!1,feedback:"غير صحيح: تسليمها لشخص خارج الإجراءات لا يحمي صاحبها."},{text:"أن يرفض، ويؤمّن النقود، ويسلّمها إلى القائد وفق الإجراءات لتُسجَّل وتُعاد.",correct:!0,feedback:"صحيح: النزاهة تعني ألا يؤخذ شيء، وأن تُسلَّم الممتلكات التي يُعثر عليها وتُسجَّل."}]},caseStudy:[{prompt:"بعد ساعات في حريق كبير في يوم حار، يشعر منتسب بدوار وتعب شديد، لكنه لا يريد أن يبدو ضعيفًا. ماذا ينبغي أن يفعل؟",options:[{text:"أن يواصل العمل حتى يُخمد الحريق.",correct:!1,feedback:"غير صحيح: الإرهاق والحر قد يُسقطانه في مكان خطر."},{text:"أن يُبلغ مشرفه فورًا ويذهب إلى منطقة الراحة ليستريح ويشرب ويُفحص.",correct:!0,feedback:"صحيح: التناوب والراحة يحميان المنتسب والفريق."},{text:"أن ينزع سترة الوقاية ويواصل العمل.",correct:!1,feedback:"غير صحيح: نزع الوقاية في المنطقة الخطرة يعرّضه للحروق والدخان."}]},{prompt:"بعد أسبوع، لا يستطيع المنتسب نفسه النوم، وتظل صور الحريق تعود إليه. ما أفضل خطوة؟",options:[{text:"أن يتحدث مع مشرفه أو زميل يثق به أو مختص، وأن يستفيد من أي دعم تقدّمه المؤسسة.",correct:!0,feedback:"صحيح: الضغط النفسي بعد حادث صعب أمر طبيعي، والدعم يساعد على التعافي."},{text:"أن يُخفي ذلك حتى لا يشكّ أحد في قدرته.",correct:!1,feedback:"غير صحيح: إخفاء الضيق قد يزيده سوءًا ويؤثر في سلامته في العمل."},{text:"أن يستقيل فورًا دون أن يخبر أحدًا.",correct:!1,feedback:"غير صحيح: مع الدعم يتعافى معظم الناس، ولا حاجة إلى قرار مفاجئ."},{text:"أن يشاهد مقاطع الحريق ليعتاد عليها.",correct:!1,feedback:"غير صحيح: تكرار الصور لا يساعد وقد يزيد الضيق."}]}],realCase:"سيناريو توضيحي: في عملية ليلية طويلة بعد انهيار مبنى، أنشأ القائد منطقة للراحة ونظّم تناوب الفرق. رفض منتسب شاب الراحة في البداية، لكن قائد فريقه أصرّ. فشرب وأكل وفُحص، ثم عاد إلى العمل يقظًا. وفي نهاية المناوبة تحدّث الفريق معًا عما رأوه. وقال المنتسب الشاب لاحقًا إن ذلك الحديث ساعده على النوم. وكان الفريق قد عمل ساعات طويلة دون أي إصابة، وشكره من أنقذهم على احترامه ورعايته.",quiz:[{question:"ماذا يعني الحياد لمنتسب الدفاع المدني؟",options:[{text:"أن تذهب المساعدة إلى الجميع بحسب الحاجة، دون تمييز.",correct:!0},{text:"أن تذهب المساعدة أولًا إلى من يعرفهم المنتسب.",correct:!1},{text:"أن تذهب المساعدة أولًا إلى من يدفعون المال.",correct:!1},{text:"أن تذهب المساعدة فقط إلى سكان المدينة نفسها.",correct:!1}],explanation:"الحياد يعني أن الحاجة وحدها تحدد من يُساعَد أولًا."},{question:"عثر منتسب على مجوهرات في أثناء البحث في بيت محترق. ما التصرف الصحيح؟",options:[{text:"أن يحتفظ بها في بيته حتى يسأل صاحبها.",correct:!1},{text:"أن يعطيها لجار يعرف الأسرة.",correct:!1},{text:"أن يسلّمها إلى القائد وفق الإجراءات لتُسجَّل.",correct:!0},{text:"أن يتركها مكانها دون إخبار أحد.",correct:!1}],explanation:"تُسلَّم الممتلكات التي يُعثر عليها وتُسجَّل لتُعاد إلى أصحابها."},{question:"لماذا يتناوب المنتسبون ويستريحون في العمليات الطويلة؟",options:[{text:"لإتاحة الوقت لوسائل الإعلام للتصوير.",correct:!1},{text:"لأن الإرهاق والحر يزيدان خطر الإصابة والأخطاء.",correct:!0},{text:"لأن القانون يشترط استراحة ثابتة كل ساعة.",correct:!1},{text:"ليتسلّم المتطوعون المنطقة الساخنة.",correct:!1}],explanation:"الراحة والماء والطعام تعيد للمنتسبين قوتهم ليعملوا بأمان."},{question:"أي سلوك على مواقع التواصل يتفق مع قيم منتسب الدفاع المدني؟",options:[{text:"نشر صور الضحايا لإظهار صعوبة العمل.",correct:!1},{text:"مشاركة أعداد غير مؤكدة للضحايا.",correct:!1},{text:"ارتداء الزي الرسمي في إعلان تجاري.",correct:!1},{text:"مشاركة رسائل السلامة الرسمية للدفاع المدني فقط.",correct:!0}],explanation:"لا يُستخدم الزي والمعلومات إلا للخدمة ومع احترام الخصوصية."},{question:"من أين يأخذ الراغب في العمل بالدفاع المدني شروط التوظيف؟",options:[{text:"من صديق عمل هناك مرة.",correct:!1},{text:"من منشور على مواقع التواصل.",correct:!1},{text:"من الإعلانات الرسمية للمديرية.",correct:!0},{text:"من أي منتسب يلقاه في حادث.",correct:!1}],explanation:"تحدد المديرية شروط التوظيف وتُنشر رسميًّا."},{question:"ما الرسالة التي تسري في مقرر عمل الدفاع المدني كله؟",options:[{text:"الحياة أولًا وسلامة الفريق أولًا.",correct:!0},{text:"تُحمى الممتلكات قبل الناس.",correct:!1},{text:"ينبغي لكل جهة أن تعمل وحدها.",correct:!1},{text:"الاستجابة أهم من الوقاية.",correct:!1}],explanation:"يقوم كل درس على الحياة أولًا، وسلامة الفريق، والقيادة الواحدة، والوقاية، والمواطنين شركاء."}]}],e={lessons:t};export{e as default,t as lessons};
